const lessons=[
{name:'Faktor & kelipatan',type:'DASAR',desc:'Kenali faktor dan kelipatan sebelum mulai menghitung.',tip:'Faktor membagi habis. Kelipatan didapat dari perkalian.',qs:[
['Tuliskan semua faktor dari 12.','1,2,3,4,6,12','Pisahkan dengan koma: 1, 2, 3, 4, 6, 12.'],['Tuliskan semua faktor dari 18.','1,2,3,6,9,18','Pisahkan dengan koma: 1, 2, 3, 6, 9, 18.'],['Tuliskan lima kelipatan pertama dari 4.','4,8,12,16,20','Pisahkan dengan koma: 4, 8, 12, 16, 20.'],['Tuliskan lima kelipatan pertama dari 7.','7,14,21,28,35','Pisahkan dengan koma: 7, 14, 21, 28, 35.'],['Apakah 5 merupakan faktor dari 35? Jawab ya atau tidak.','ya','Ya, karena 35 ÷ 5 = 7.'],['Apakah 8 merupakan faktor dari 30? Jawab ya atau tidak.','tidak','Tidak, karena 30 tidak habis dibagi 8.'],['Apakah 36 merupakan kelipatan dari 6? Jawab ya atau tidak.','ya','Ya, karena 6 × 6 = 36.'],['Apakah 45 merupakan kelipatan dari 8? Jawab ya atau tidak.','tidak','Tidak, 45 bukan hasil perkalian 8 dengan bilangan bulat.'],['Tuliskan faktor persekutuan dari 12 dan 18.','1,2,3,6','Faktor yang sama: 1, 2, 3, 6.'],['Tuliskan tiga kelipatan persekutuan positif terkecil dari 2 dan 3.','6,12,18','Kelipatan bersama pertama: 6, lalu 12 dan 18.']]},
{name:'Mengenal FPB',type:'LATIHAN FPB',desc:'Cari faktor terbesar yang dimiliki bersama.',tip:'FPB berguna saat membagi benda menjadi kelompok sama banyak sebanyak mungkin.',qs:[
['Faktor 8: 1, 2, 4, 8. Faktor 12: 1, 2, 3, 4, 6, 12. Berapa FPB-nya?','4','Faktor bersama terbesar adalah 4.'],['Tentukan FPB dari 10 dan 15.','5','Faktor bersama terbesarnya adalah 5.'],['Tentukan FPB dari 14 dan 21.','7','Faktor bersama terbesarnya adalah 7.'],['Tentukan FPB dari 16 dan 24.','8','Faktor bersama terbesarnya adalah 8.'],['Tentukan FPB dari 18 dan 30.','6','Faktor bersama terbesarnya adalah 6.'],['Tentukan FPB dari 20 dan 28.','4','Faktor bersama terbesarnya adalah 4.'],['Tentukan FPB dari 24 dan 36.','12','Faktor bersama terbesarnya adalah 12.'],['Tentukan FPB dari 27 dan 36.','9','Faktor bersama terbesarnya adalah 9.'],['Tentukan FPB dari 32 dan 40.','8','Faktor bersama terbesarnya adalah 8.'],['Tentukan FPB dari 42 dan 56.','14','Faktor bersama terbesarnya adalah 14.']]},
{name:'Cerita FPB',type:'SOAL CERITA',desc:'Gunakan FPB untuk membagi sama rata sebanyak mungkin.',tip:'Tandai jumlah benda yang ada. Biasanya soal “kelompok paling banyak” memakai FPB.',qs:[
['Ada 12 apel dan 18 jeruk. Buah dibagi rata ke kantong. Berapa kantong paling banyak?','6','FPB(12, 18) = 6 kantong.'],['Ada 20 roti dan 30 kue. Berapa paket paling banyak dengan isi setiap jenis sama?','10','FPB(20, 30) = 10 paket.'],['Ada 24 pensil dan 36 penghapus. Berapa kelompok paling banyak dengan pembagian rata?','12','FPB(24, 36) = 12 kelompok.'],['Ada 16 buku cerita dan 24 buku gambar. Berapa murid paling banyak yang menerima bagian sama?','8','FPB(16, 24) = 8 murid.'],['Tali 28 cm dan 42 cm dipotong sama panjang, sepanjang mungkin. Berapa cm tiap potong?','14','FPB(28, 42) = 14 cm.'],['Ada 18 mawar dan 27 melati. Berapa buket paling banyak dengan komposisi sama?','9','FPB(18, 27) = 9 buket.'],['Ada 32 stiker dan 40 kartu dibagikan sama rata. Berapa teman paling banyak?','8','FPB(32, 40) = 8 teman.'],['Ada 45 kelereng merah dan 60 biru. Berapa kantong paling banyak dengan isi sama?','15','FPB(45, 60) = 15 kantong.'],['Pita 36 cm dan 48 cm dipotong sama panjang, sepanjang mungkin. Berapa cm tiap potong?','12','FPB(36, 48) = 12 cm.'],['Ada 24 mangga dan 32 jeruk dibagi rata ke keranjang. Berapa keranjang paling banyak?','8','FPB(24, 32) = 8 keranjang.']]},
{name:'Mengenal KPK',type:'LATIHAN KPK',desc:'Temukan kelipatan bersama yang paling kecil.',tip:'Tuliskan beberapa kelipatan. KPK adalah angka pertama yang muncul di kedua daftar.',qs:[
['Tuliskan lima kelipatan pertama dari 3.','3,6,9,12,15','Kelipatan pertama: 3, 6, 9, 12, 15.'],['Tuliskan lima kelipatan pertama dari 5.','5,10,15,20,25','Kelipatan pertama: 5, 10, 15, 20, 25.'],['Tentukan KPK dari 2 dan 4.','4','Kelipatan bersama terkecilnya adalah 4.'],['Tentukan KPK dari 3 dan 5.','15','Kelipatan bersama terkecilnya adalah 15.'],['Tentukan KPK dari 4 dan 6.','12','Kelipatan bersama terkecilnya adalah 12.'],['Tentukan KPK dari 5 dan 10.','10','Kelipatan bersama terkecilnya adalah 10.'],['Tentukan KPK dari 6 dan 8.','24','Kelipatan bersama terkecilnya adalah 24.'],['Tentukan KPK dari 7 dan 9.','63','Kelipatan bersama terkecilnya adalah 63.'],['Tentukan KPK dari 8 dan 12.','24','Kelipatan bersama terkecilnya adalah 24.'],['Tentukan KPK dari 10 dan 15.','30','Kelipatan bersama terkecilnya adalah 30.']]},
{name:'Cerita KPK',type:'SOAL CERITA',desc:'Gunakan KPK untuk mencari kapan dua kejadian berulang bersama.',tip:'Kata seperti “bersama lagi” atau “kapan bertemu lagi” biasanya petunjuk KPK.',qs:[
['Lampu A berkedip tiap 2 detik dan B tiap 3 detik. Kapan keduanya berkedip bersama lagi?','6','KPK(2, 3) = 6 detik.'],['Bel pertama berbunyi tiap 4 menit, kedua tiap 6 menit. Kapan berbunyi bersama lagi?','12','KPK(4, 6) = 12 menit.'],['Bus A berangkat tiap 5 menit dan B tiap 10 menit. Berapa menit lagi berangkat bersama?','10','KPK(5, 10) = 10 menit.'],['Dita berenang tiap 3 hari, Rani tiap 4 hari. Berapa hari lagi berenang bersama?','12','KPK(3, 4) = 12 hari.'],['Dua mesin menyala tiap 6 menit dan 8 menit. Kapan menyala bersama lagi?','24','KPK(6, 8) = 24 menit.'],['Tanaman A disiram tiap 4 hari dan B tiap 9 hari. Kapan jadwalnya bersamaan?','36','KPK(4, 9) = 36 hari.'],['Riko latihan sepak bola tiap 7 hari dan basket tiap 14 hari. Kapan bersamaan?','14','KPK(7, 14) = 14 hari.'],['Dua alarm berbunyi tiap 8 dan 12 menit. Kapan bunyi bersama lagi?','24','KPK(8, 12) = 24 menit.'],['Kereta A tiba tiap 10 menit dan B tiap 15 menit. Kapan tiba bersama?','30','KPK(10, 15) = 30 menit.'],['Les matematika tiap 6 hari dan bahasa tiap 9 hari. Kapan jadwalnya bersamaan?','18','KPK(6, 9) = 18 hari.']]},
{name:'Campuran FPB/KPK',type:'CAMPURAN',desc:'Pilih sendiri: soal ini perlu FPB atau KPK?',tip:'“Paling banyak dibagi rata” = FPB. “Bersama lagi” = KPK.',qs:[
['Tentukan FPB dari 12 dan 20.','4','FPB(12, 20) = 4.'],['Tentukan KPK dari 4 dan 10.','20','KPK(4, 10) = 20.'],['Tali 30 cm dan 45 cm dipotong sama panjang sepanjang mungkin. Berapa cm tiap potong?','15','Cari FPB: FPB(30, 45) = 15 cm.'],['Alarm berbunyi setiap 5 dan 8 menit. Kapan bunyi bersama lagi?','40','Cari KPK: KPK(5, 8) = 40 menit.'],['Ada 28 jeruk dan 42 apel dibagi rata ke kantong. Berapa kantong paling banyak?','14','Cari FPB: FPB(28, 42) = 14 kantong.'],['Tentukan KPK dari 6 dan 9.','18','KPK(6, 9) = 18.'],['Tentukan FPB dari 36 dan 48.','12','FPB(36, 48) = 12.'],['Lampu menyala tiap 3 dan 7 detik. Kapan menyala bersama lagi?','21','Cari KPK: KPK(3, 7) = 21 detik.'],['Ada 40 pensil dan 56 penghapus dibagi rata. Berapa kelompok paling banyak?','8','Cari FPB: FPB(40, 56) = 8 kelompok.'],['Tentukan KPK dari 8 dan 10.','40','KPK(8, 10) = 40.']]},
{name:'Tantangan akhir',type:'TANTANGAN',desc:'Tunjukkan bahwa kamu sudah bisa membedakan FPB dan KPK.',tip:'Sebelum menghitung, sebutkan alasannya: membagi rata atau mencari kejadian berulang?',qs:[
['Tentukan FPB dari 42 dan 56.','14','FPB(42, 56) = 14.'],['Tentukan KPK dari 12 dan 18.','36','KPK(12, 18) = 36.'],['Ada 48 kue dan 60 permen dibagikan rata. Berapa anak paling banyak yang menerima?','12','Cari FPB: FPB(48, 60) = 12 anak.'],['Dua bus tiba tiap 12 dan 20 menit. Kapan tiba bersama lagi?','60','Cari KPK: KPK(12, 20) = 60 menit.'],['Ada 54 mawar dan 72 melati dibuat buket dengan komposisi sama. Berapa buket paling banyak?','18','Cari FPB: FPB(54, 72) = 18 buket.'],['Tentukan FPB dari 45 dan 75.','15','FPB(45, 75) = 15.'],['Tentukan KPK dari 14 dan 21.','42','KPK(14, 21) = 42.'],['Beni olahraga tiap 4 hari, Doni tiap 6 hari. Kapan berolahraga bersama lagi?','12','Cari KPK: KPK(4, 6) = 12 hari.'],['Pita 64 cm dan 80 cm dipotong sama panjang, sepanjang mungkin. Berapa cm tiap potong?','16','Cari FPB: FPB(64, 80) = 16 cm.'],['Tentukan KPK dari 15 dan 20.','60','KPK(15, 20) = 60.']]}
,{name:'Tantangan Expert: Jam & tanggal',type:'EXPERT',desc:'Pilih FPB atau KPK dari petunjuk waktu, lalu hitung dengan teliti.',tip:'Untuk jadwal berulang yang bertemu lagi, cari KPK. Untuk membagi durasi menjadi potongan sama yang paling panjang, cari FPB.',qs:[
['Alarm A berbunyi setiap 18 menit dan alarm B setiap 24 menit. Keduanya berbunyi bersama pukul 07.00. Pukul berapa keduanya berbunyi bersama lagi?',['08:12','8:12'],'KPK(18, 24) = 72 menit. 07.00 + 72 menit = 08.12.'],
['Bus A berangkat setiap 35 menit dan bus B setiap 50 menit. Keduanya berangkat bersama pukul 06.30. Kapan berangkat bersama lagi?',['12:20','12.20'],'KPK(35, 50) = 350 menit = 5 jam 50 menit. Pukul 06.30 + 5 jam 50 menit = 12.20.'],
['Lonceng A berbunyi setiap 12 menit dan lonceng B setiap 20 menit. Keduanya berbunyi pukul 09.15. Pukul berapa berbunyi bersama lagi?',['10:15','10.15'],'KPK(12, 20) = 60 menit. Satu jam setelah 09.15 adalah 10.15.'],
['Pengingat obat A muncul setiap 6 jam dan B setiap 8 jam. Keduanya muncul Selasa pukul 05.00. Kapan muncul bersama lagi?',['Rabu 05:00','Rabu 05.00','Rabu pukul 05:00'],'KPK(6, 8) = 24 jam. Jadi pengingat bersama lagi pada Rabu pukul 05.00.'],
['Lampu merah berkedip setiap 45 detik dan lampu hijau setiap 60 detik. Keduanya berkedip pukul 12.00. Pukul berapa berkedip bersama lagi?',['12:03','12.03'],'KPK(45, 60) = 180 detik = 3 menit. Jadi waktunya pukul 12.03.'],
['Rara mengunjungi perpustakaan setiap 6 hari dan Dini setiap 8 hari. Mereka datang bersama pada 3 Mei. Tanggal berapa mereka datang bersama lagi?',['27 Mei','27/5'],'KPK(6, 8) = 24 hari. Tanggal 3 Mei ditambah 24 hari adalah 27 Mei.'],
['Pasar sekolah diadakan setiap 9 hari dan klub sains bertemu setiap 12 hari. Keduanya berlangsung pada 4 Maret. Tanggal berapa jadwalnya bersamaan lagi?',['9 April','9/4'],'KPK(9, 12) = 36 hari. Dari 4 Maret, 36 hari kemudian adalah 9 April.'],
['Alya berlatih piano setiap 14 hari dan berenang setiap 21 hari. Kedua kegiatan jatuh pada 5 Agustus. Tanggal berapa keduanya jatuh bersamaan lagi?',['16 September','16/9'],'KPK(14, 21) = 42 hari. Dari 5 Agustus, 42 hari kemudian adalah 16 September.'],
['Dua rekaman latihan berdurasi 96 menit dan 144 menit akan dibagi menjadi bagian-bagian sama panjang tanpa sisa. Berapa durasi terpanjang setiap bagian?',['48 menit','48'],'FPB(96, 144) = 48. Jadi setiap bagian dapat berdurasi 48 menit.'],
['Dua sesi kegiatan berdurasi 150 menit dan 210 menit akan dipecah menjadi blok waktu sama panjang tanpa sisa. Berapa durasi blok paling panjang?',['30 menit','30'],'FPB(150, 210) = 30. Jadi blok paling panjang adalah 30 menit.']
]}
,{name:'Pecahan senilai & membandingkan',type:'PECAHAN',desc:'Sederhanakan, temukan pecahan senilai, lalu bandingkan dan urutkan pecahan.',tip:'Jika penyebut sama, bandingkan pembilang. Jika penyebut berbeda, ubah dulu menjadi pecahan senilai dengan penyebut sama.',lessonNote:'<b>Bekal Pecahan</b><span>Pecahan senilai memiliki nilai yang sama, walau angka pembilang dan penyebutnya berbeda.</span><span>Untuk membandingkan pecahan berpenyebut berbeda, samakan penyebutnya. Untuk menyederhanakan, bagi pembilang dan penyebut dengan angka yang sama.</span><small>Contoh: 3/4 = 9/12, jadi 3/4 lebih besar daripada 8/12.</small>',qs:[
['Sederhanakan pecahan 6/8.',['3/4'],'Bagi pembilang dan penyebut dengan 2: 6/8 = 3/4.'],
['Pecahan yang senilai dengan 2/3 dan berpenyebut 12 adalah berapa?',['8/12'],'Kalikan pembilang dan penyebut 2/3 dengan 4: 8/12.'],
['Isi tanda yang tepat: 3/5 ___ 4/5.',['<'],'Penyebutnya sama. Karena 3 lebih kecil daripada 4, maka 3/5 < 4/5.'],
['Isi tanda yang tepat: 5/6 ___ 4/5.',['>'],'Samakan penyebut menjadi 30: 5/6 = 25/30 dan 4/5 = 24/30. Jadi 5/6 > 4/5.'],
['Ubah 7/4 menjadi pecahan campuran.',['1 3/4','1¾'],'7 dibagi 4 hasilnya 1 sisa 3, jadi 7/4 = 1 3/4.'],
['Ubah 2 1/3 menjadi pecahan biasa.',['7/3'],'Dua utuh sama dengan 6/3. Tambahkan 1/3, hasilnya 7/3.'],
['Urutkan dari yang terkecil: 1/2, 3/4, 2/3.',['1/2, 2/3, 3/4'],'Dengan penyebut 12: 1/2 = 6/12, 2/3 = 8/12, dan 3/4 = 9/12.'],
['Agar 3/4 senilai dengan pecahan berpenyebut 20, pembilangnya harus berapa?',['15'],'Penyebut 4 dikali 5 menjadi 20, maka pembilang 3 juga dikali 5: 15/20.'],
['Manakah yang lebih besar, 5/8 atau 3/4?',['3/4'],'Ubah 3/4 menjadi 6/8. Karena 6/8 lebih besar daripada 5/8, jawabannya 3/4.'],
['Hanum makan 3/8 bagian kue. Rani makan 1/4 bagian kue yang sama besar. Siapa makan lebih banyak?',['Hanum'],'Ubah 1/4 menjadi 2/8. Karena 3/8 > 2/8, Hanum makan lebih banyak.']
]}
,{name:'Penjumlahan pecahan',type:'PECAHAN',desc:'Menjumlahkan pecahan berpenyebut sama maupun berbeda dan menyederhanakan hasilnya.',tip:'Jika penyebut berbeda, samakan penyebut terlebih dahulu. Setelah itu, jumlahkan pembilang dan sederhanakan hasilnya.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menjumlahkan pecahan biasa dan pecahan campuran, lalu menggunakan hasilnya dalam soal sehari-hari.</span><b>Petunjuk Konsep</b><span>Penyebut menunjukkan ukuran bagian, jadi pecahan hanya dapat langsung dijumlahkan jika penyebutnya sama.</span><small>Contoh: 1/2 + 1/4 = 2/4 + 1/4 = 3/4.</small>',qs:[
['Hitung 2/7 + 3/7.',['5/7'],'Penyebut sudah sama. Jumlahkan pembilangnya: 2 + 3 = 5, jadi hasilnya 5/7.'],
['Hitung 1/4 + 2/4.',['3/4'],'Penyebut sudah sama. Jumlahkan 1 + 2, sehingga hasilnya 3/4.'],
['Hitung 1/2 + 1/4.',['3/4'],'Ubah 1/2 menjadi 2/4. Jadi 2/4 + 1/4 = 3/4.'],
['Hitung 2/3 + 1/6.',['5/6'],'Ubah 2/3 menjadi 4/6. Jadi 4/6 + 1/6 = 5/6.'],
['Hitung 3/8 + 1/4.',['5/8'],'Ubah 1/4 menjadi 2/8. Jadi 3/8 + 2/8 = 5/8.'],
['Hitung 5/6 + 2/3.',['1 1/2','1½','3/2'],'Ubah 2/3 menjadi 4/6. Hasilnya 9/6 = 3/2 = 1 1/2.'],
['Hitung 1 1/4 + 2 1/4.',['3 1/2','3½','7/2'],'Jumlahkan bagian utuh: 1 + 2 = 3. Lalu 1/4 + 1/4 = 2/4 = 1/2, jadi 3 1/2.'],
['Isi bagian yang kosong: 1/5 + ___ = 4/5.',['3/5'],'Karena 1/5 + 3/5 = 4/5, bagian yang kosong adalah 3/5.'],
['Hanum minum 3/10 liter jus pagi hari dan 2/5 liter siang hari. Berapa liter jumlah jus yang diminum?',['7/10','0,7 liter','0,7'],'Ubah 2/5 menjadi 4/10. Jadi 3/10 + 4/10 = 7/10 liter.'],
['Pita merah panjangnya 3/4 meter dan pita biru 5/6 meter. Berapa meter panjang keduanya?',['1 7/12','1 7/12 meter','19/12'],'Samakan penyebut menjadi 12: 3/4 = 9/12 dan 5/6 = 10/12. Jumlahnya 19/12 = 1 7/12 meter.']
]}
,{name:'Pengurangan pecahan',type:'PECAHAN',desc:'Mengurangkan pecahan berpenyebut sama maupun berbeda dan menyederhanakan hasilnya.',tip:'Samakan penyebut terlebih dahulu. Jika bilangan atas belum cukup untuk dikurangi, pinjam satu bagian utuh lalu ubah menjadi pecahan.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat mengurangkan pecahan biasa dan pecahan campuran, lalu memakainya untuk menyelesaikan masalah sehari-hari.</span><b>Petunjuk Konsep</b><span>Setelah penyebut sama, kurangkan pembilangnya saja. Sederhanakan hasil akhir jika pembilang dan penyebut masih dapat dibagi angka yang sama.</span><small>Contoh: 3/4 − 1/2 = 3/4 − 2/4 = 1/4.</small>',qs:[
['Hitung 6/9 − 2/9.',['4/9'],'Penyebut sudah sama. Kurangkan pembilangnya: 6 − 2 = 4, jadi hasilnya 4/9.'],
['Hitung 7/8 − 3/8.',['1/2','4/8'],'Penyebut sudah sama: 7/8 − 3/8 = 4/8. Sederhanakan menjadi 1/2.'],
['Hitung 3/4 − 1/2.',['1/4'],'Ubah 1/2 menjadi 2/4. Jadi 3/4 − 2/4 = 1/4.'],
['Hitung 5/6 − 1/3.',['1/2','3/6'],'Ubah 1/3 menjadi 2/6. Jadi 5/6 − 2/6 = 3/6 = 1/2.'],
['Hitung 7/10 − 1/4.',['9/20'],'Samakan penyebut menjadi 20: 7/10 = 14/20 dan 1/4 = 5/20. Selisihnya 9/20.'],
['Satu kue utuh dikurangi 3/8 bagian. Berapa bagian yang tersisa?',['5/8'],'Satu utuh sama dengan 8/8. Jadi 8/8 − 3/8 = 5/8.'],
['Hitung 2 1/3 − 1 2/3.',['2/3'],'Pinjam satu utuh: 2 1/3 = 1 4/3. Jadi 1 4/3 − 1 2/3 = 2/3.'],
['Isi bagian yang kosong: 5/6 − ___ = 1/3.',['1/2','3/6'],'Ubah 1/3 menjadi 2/6. Pecahan yang dicari adalah 5/6 − 2/6 = 3/6 = 1/2.'],
['Hanum memiliki 7/8 bagian kue lalu memakan 3/8 bagian. Berapa bagian kue yang tersisa?',['1/2','4/8'],'Kurangkan pecahan berpenyebut sama: 7/8 − 3/8 = 4/8 = 1/2 bagian.'],
['Pita Hanum panjangnya 2 1/4 meter. Setelah dipakai 5/6 meter, berapa meter sisanya?',['1 5/12','1 5/12 meter','17/12'],'Ubah ke penyebut 12: 2 1/4 = 27/12 dan 5/6 = 10/12. Sisanya 17/12 = 1 5/12 meter.']
]}
,{name:'Perkalian pecahan & bilangan asli',type:'PECAHAN',desc:'Mengalikan pecahan dengan bilangan asli dan menyederhanakan hasilnya.',tip:'Kalikan bilangan asli dengan pembilang, sedangkan penyebut tetap. Setelah itu, sederhanakan atau ubah menjadi pecahan campuran.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat mengalikan pecahan biasa atau campuran dengan bilangan asli dan menerapkannya pada soal sehari-hari.</span><b>Petunjuk Konsep</b><span>Perkalian pecahan dengan bilangan asli berarti penjumlahan berulang. Ubah pecahan campuran menjadi pecahan biasa sebelum menghitung.</span><small>Contoh: 3 × 2/5 = 2/5 + 2/5 + 2/5 = 6/5 = 1 1/5.</small>',qs:[
['Hitung 3 × 1/5.',['3/5'],'Kalikan 3 dengan pembilang 1: (3 × 1)/5 = 3/5.'],
['Hitung 4 × 2/7.',['1 1/7','8/7'],'Hasilnya 8/7. Ubah menjadi pecahan campuran: 1 1/7.'],
['Hitung 5 × 3/10.',['1 1/2','1½','3/2','15/10'],'Hasilnya 15/10. Sederhanakan menjadi 3/2 = 1 1/2.'],
['Hitung 2/3 × 6.',['4'],'Kalikan pembilang dengan 6: 12/3 = 4.'],
['Hitung 7 × 3/14.',['1 1/2','1½','3/2','21/14'],'Hasilnya 21/14. Sederhanakan menjadi 3/2 = 1 1/2.'],
['Isi angka yang kosong: ___ × 1/4 = 3/4.',['3'],'Tiga kali 1/4 adalah 1/4 + 1/4 + 1/4 = 3/4.'],
['Hitung 2 1/3 × 3.',['7'],'Ubah 2 1/3 menjadi 7/3. Lalu 7/3 × 3 = 21/3 = 7.'],
['Setiap paket berisi 3/8 kg buah. Berapa kg buah dalam 4 paket?',['1 1/2 kg','1 1/2','1½ kg','1½','3/2 kg','3/2'],'Hitung 4 × 3/8 = 12/8 = 3/2 = 1 1/2 kg.'],
['Hanum berjalan 2/5 km setiap hari selama 5 hari. Berapa km seluruh jaraknya?',['2 km','2'],'Hitung 5 × 2/5 = 10/5 = 2 km.'],
['Satu resep membutuhkan 1 1/4 cangkir tepung. Berapa cangkir untuk 3 resep?',['3 3/4 cangkir','3 3/4','3¾ cangkir','3¾','15/4'],'Ubah 1 1/4 menjadi 5/4. Lalu 3 × 5/4 = 15/4 = 3 3/4 cangkir.']
]}
,{name:'Pembagian pecahan & bilangan asli',type:'PECAHAN',desc:'Membagi pecahan dengan bilangan asli dan menyederhanakan hasilnya.',tip:'Membagi pecahan dengan bilangan asli sama dengan mengalikan penyebut dengan bilangan tersebut. Sederhanakan hasil akhirnya.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat membagi pecahan biasa atau campuran dengan bilangan asli dan menerapkannya dalam pembagian sama rata.</span><b>Petunjuk Konsep</b><span>Pecahan ÷ bilangan asli dapat dihitung dengan mempertahankan pembilang dan mengalikan penyebutnya. Ubah pecahan campuran menjadi pecahan biasa terlebih dahulu.</span><small>Contoh: 3/4 ÷ 2 = 3/(4 × 2) = 3/8.</small>',qs:[
['Hitung 1/2 ÷ 2.',['1/4'],'Kalikan penyebut dengan 2: 1/(2 × 2) = 1/4.'],
['Hitung 3/4 ÷ 3.',['1/4','3/12'],'Hasilnya 3/12. Sederhanakan dengan membagi 3, sehingga menjadi 1/4.'],
['Hitung 5/6 ÷ 5.',['1/6','5/30'],'Hasilnya 5/30. Sederhanakan dengan membagi 5, sehingga menjadi 1/6.'],
['Hitung 4/5 ÷ 2.',['2/5','4/10'],'Hasilnya 4/10. Sederhanakan dengan membagi 2, sehingga menjadi 2/5.'],
['Hitung 7/8 ÷ 7.',['1/8','7/56'],'Hasilnya 7/56. Sederhanakan dengan membagi 7, sehingga menjadi 1/8.'],
['Hitung 2/3 ÷ 4.',['1/6','2/12'],'Hasilnya 2/12. Sederhanakan dengan membagi 2, sehingga menjadi 1/6.'],
['Hitung 1 1/2 ÷ 3.',['1/2','3/6'],'Ubah 1 1/2 menjadi 3/2. Kemudian 3/2 ÷ 3 = 3/6 = 1/2.'],
['Isi angka yang kosong: 3/5 ÷ ___ = 1/5.',['3'],'Tiga per lima dibagi 3 sama dengan 3/15, lalu disederhanakan menjadi 1/5.'],
['Sebanyak 3/4 liter jus dibagi rata ke 3 gelas. Berapa liter isi setiap gelas?',['1/4 liter','1/4'],'Hitung 3/4 ÷ 3 = 3/12 = 1/4 liter.'],
['Pita sepanjang 2 2/5 meter dipotong menjadi 4 bagian sama panjang. Berapa meter panjang setiap bagian?',['3/5 meter','3/5'],'Ubah 2 2/5 menjadi 12/5. Kemudian 12/5 ÷ 4 = 12/20 = 3/5 meter.']
]}
,{name:'Menghubungkan pecahan & desimal',type:'PECAHAN',desc:'Mengubah pecahan sederhana menjadi desimal satu angka dan sebaliknya.',tip:'Angka pertama setelah koma menunjukkan persepuluhan. Samakan penyebut pecahan menjadi 10 agar bentuk desimal mudah terlihat.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menghubungkan pecahan berpenyebut 2, 5, atau 10 dengan bilangan desimal satu angka.</span><b>Petunjuk Konsep</b><span>Ubah pecahan menjadi pecahan senilai berpenyebut 10. Pembilangnya menjadi angka pertama setelah koma. Sebaliknya, desimal satu angka dapat ditulis sebagai pecahan berpenyebut 10 lalu disederhanakan.</span><small>Contoh: 1/2 = 5/10 = 0,5 dan 0,6 = 6/10 = 3/5.</small>',qs:[
['Ubah 3/10 menjadi bilangan desimal.',['0,3','0.3'],'Tiga per sepuluh berarti tiga bagian persepuluhan, sehingga ditulis 0,3.'],
['Ubah 7/10 menjadi bilangan desimal.',['0,7','0.7'],'Tujuh per sepuluh ditulis sebagai 0,7.'],
['Ubah 1/2 menjadi bilangan desimal.',['0,5','0.5'],'Kalikan pembilang dan penyebut dengan 5: 1/2 = 5/10 = 0,5.'],
['Ubah 2/5 menjadi bilangan desimal.',['0,4','0.4'],'Kalikan pembilang dan penyebut dengan 2: 2/5 = 4/10 = 0,4.'],
['Ubah 3/5 menjadi bilangan desimal.',['0,6','0.6'],'Kalikan pembilang dan penyebut dengan 2: 3/5 = 6/10 = 0,6.'],
['Ubah 4/5 menjadi bilangan desimal.',['0,8','0.8'],'Kalikan pembilang dan penyebut dengan 2: 4/5 = 8/10 = 0,8.'],
['Isi bagian kosong: 9/10 = ___.',['0,9','0.9'],'Sembilan per sepuluh sama dengan 0,9.'],
['Ubah 0,2 menjadi pecahan paling sederhana.',['1/5','2/10'],'Bilangan 0,2 berarti 2/10. Sederhanakan dengan membagi 2 sehingga menjadi 1/5.'],
['Sebuah botol berisi 0,5 liter air. Tuliskan 0,5 sebagai pecahan paling sederhana.',['1/2','5/10'],'Bilangan 0,5 = 5/10. Sederhanakan dengan membagi 5 sehingga menjadi 1/2 liter.'],
['Mana yang lebih besar: 3/5 atau 0,7?',['0,7','0.7','7/10'],'Ubah 3/5 menjadi 6/10 = 0,6. Karena 0,7 lebih besar daripada 0,6, jawabannya 0,7.']
]}
,{name:'Membandingkan & mengurutkan desimal',type:'DESIMAL',desc:'Membandingkan dan mengurutkan bilangan desimal satu angka di belakang koma.',tip:'Bandingkan angka pada tempat persepuluhan. Pada garis bilangan, nilai yang lebih besar berada lebih ke kanan.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat membandingkan dan mengurutkan bilangan desimal satu angka menggunakan tanda &lt;, &gt;, dan =.</span><b>Petunjuk Konsep</b><span>Perhatikan angka satuan terlebih dahulu. Jika satuannya sama, bandingkan angka persepuluhannya. Gunakan &lt; untuk lebih kecil, &gt; untuk lebih besar, dan = untuk sama dengan.</span><small>Contoh: 0,3 &lt; 0,6 karena 3 persepuluhan lebih kecil daripada 6 persepuluhan.</small>',qs:[
['Isi dengan tanda <, >, atau =: 0,3 ___ 0,7.',['<'],'Tiga persepuluhan lebih kecil daripada tujuh persepuluhan, jadi 0,3 < 0,7.'],
['Isi dengan tanda <, >, atau =: 0,9 ___ 0,4.',['>'],'Sembilan persepuluhan lebih besar daripada empat persepuluhan, jadi 0,9 > 0,4.'],
['Isi dengan tanda <, >, atau =: 0,5 ___ 0,5.',['='],'Kedua bilangan memiliki nilai yang sama, jadi gunakan tanda =.'],
['Mana yang lebih besar: 0,6 atau 0,8?',['0,8','0.8'],'Delapan persepuluhan lebih besar daripada enam persepuluhan, sehingga jawabannya 0,8.'],
['Mana yang paling kecil: 0,4; 0,1; atau 0,7?',['0,1','0.1'],'Satu persepuluhan adalah nilai terkecil, sehingga jawabannya 0,1.'],
['Urutkan dari yang terkecil: 0,6; 0,2; 0,9. Gunakan tanda <.',['0,2<0,6<0,9','0.2<0.6<0.9'],'Urutkan angka persepuluhannya: 2, 6, lalu 9. Jadi 0,2 < 0,6 < 0,9.'],
['Urutkan dari yang terbesar: 0,3; 0,8; 0,5. Gunakan tanda >.',['0,8>0,5>0,3','0.8>0.5>0.3'],'Urutkan angka persepuluhannya dari terbesar: 8, 5, lalu 3. Jadi 0,8 > 0,5 > 0,3.'],
['Isi bilangan yang tepat: 0,4 < ___ < 0,6.',['0,5','0.5'],'Bilangan satu persepuluhan di antara 0,4 dan 0,6 adalah 0,5.'],
['Pita merah panjangnya 1,4 meter dan pita biru 1,7 meter. Pita mana yang lebih panjang?',['pita biru','biru'],'Satuan keduanya sama-sama 1. Bandingkan persepuluhannya: 7 lebih besar daripada 4, jadi pita biru lebih panjang.'],
['Tiga botol berisi 0,9 liter, 0,5 liter, dan 0,7 liter. Urutkan isi botol dari yang paling sedikit.',['0,5<0,7<0,9','0.5<0.7<0.9'],'Bandingkan angka persepuluhannya: 5 < 7 < 9. Urutannya adalah 0,5 < 0,7 < 0,9 liter.']
]}
,{name:'Pola bilangan membesar & mengecil',type:'POLA',desc:'Menemukan aturan dan melanjutkan pola bilangan sederhana.',tip:'Bandingkan dua bilangan yang berdekatan. Cari apakah polanya bertambah, berkurang, dikali, atau dibagi dengan angka yang sama.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat mengenali aturan, menemukan bilangan yang hilang, dan melanjutkan pola bilangan membesar atau mengecil.</span><b>Petunjuk Konsep</b><span>Amati perubahan dari satu bilangan ke bilangan berikutnya. Coba aturan tambah atau kurang terlebih dahulu, lalu periksa apakah pola memakai kali atau bagi.</span><small>Contoh: 4, 8, 12, 16 bertambah 4 setiap langkah, sehingga bilangan berikutnya adalah 20.</small>',qs:[
['Lanjutkan pola: 2, 4, 6, 8, ___.',['10'],'Setiap bilangan bertambah 2. Jadi setelah 8 adalah 10.'],
['Lanjutkan pola: 5, 10, 15, 20, ___.',['25'],'Pola bertambah 5 setiap langkah. Jadi bilangan berikutnya 25.'],
['Lanjutkan pola: 30, 27, 24, 21, ___.',['18'],'Setiap bilangan berkurang 3. Jadi setelah 21 adalah 18.'],
['Isi bilangan yang hilang: 100, 90, 80, ___, 60.',['70'],'Pola berkurang 10 setiap langkah, sehingga bilangan yang hilang adalah 70.'],
['Berapa selisih tetap pada pola 7, 14, 21, 28?',['7'],'Setiap bilangan bertambah 7: 14 − 7 = 7 dan 21 − 14 = 7.'],
['Lanjutkan pola: 3, 6, 12, 24, ___.',['48'],'Setiap bilangan dikali 2. Jadi 24 × 2 = 48.'],
['Isi bilangan yang hilang: 4, 8, ___, 16, 20.',['12'],'Pola bertambah 4, sehingga bilangan di antara 8 dan 16 adalah 12.'],
['Jumlah kancing pada empat kartu adalah 3, 5, 7, dan 9. Jika polanya berlanjut, berapa kancing pada kartu kelima?',['11'],'Jumlah kancing bertambah 2 pada setiap kartu. Jadi kartu kelima memiliki 11 kancing.'],
['Baris kursi pertama berisi 6 kursi, lalu 9, 12, dan 15 kursi. Berapa kursi pada baris berikutnya?',['18'],'Banyak kursi bertambah 3 setiap baris. Jadi baris berikutnya berisi 18 kursi.'],
['Lanjutkan pola mengecil: 81, 27, 9, 3, ___.',['1'],'Setiap bilangan dibagi 3. Jadi 3 ÷ 3 = 1.']
]}
,{name:'Mengenal rasio sederhana',type:'RASIO',desc:'Membaca, menulis, dan menyederhanakan perbandingan dua jumlah.',tip:'Rasio membandingkan dua jumlah dengan urutan yang penting. Tulis jumlah pertama : jumlah kedua, lalu sederhanakan dengan membagi keduanya memakai angka yang sama.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menuliskan, membaca, dan menyederhanakan rasio dua jumlah dalam bentuk a : b.</span><b>Petunjuk Konsep</b><span>Perhatikan urutan benda yang dibandingkan. Rasio 6 apel terhadap 3 jeruk adalah 6 : 3. Bagilah kedua bilangan dengan faktor yang sama untuk memperoleh bentuk paling sederhana.</span><small>Contoh: 6 : 3 = 2 : 1 karena kedua bilangan dibagi 3.</small>',qs:[
['Ada 4 pensil merah dan 3 pensil biru. Tuliskan rasio pensil merah terhadap pensil biru.',['4:3','4 : 3'],'Urutannya merah lalu biru, sehingga rasionya 4 : 3.'],
['Di meja ada 2 buku cerita dan 5 buku pelajaran. Tuliskan rasio buku cerita terhadap buku pelajaran.',['2:5','2 : 5'],'Urutannya buku cerita lalu buku pelajaran, sehingga rasionya 2 : 5.'],
['Sebuah keranjang berisi 6 apel dan 2 jeruk. Sederhanakan rasio apel terhadap jeruk.',['3:1','3 : 1'],'Rasio 6 : 2 disederhanakan dengan membagi keduanya dengan 2 menjadi 3 : 1.'],
['Sederhanakan rasio 8 : 12.',['2:3','2 : 3'],'FPB dari 8 dan 12 adalah 4. Bagilah keduanya dengan 4 sehingga menjadi 2 : 3.'],
['Sederhanakan rasio 15 : 10.',['3:2','3 : 2'],'Bagilah 15 dan 10 dengan 5 sehingga menjadi 3 : 2.'],
['Isi angka yang kosong agar rasionya senilai: 2 : 3 = 4 : ___.',['6'],'Rasio 2 : 3 dikali 2 menjadi 4 : 6, jadi angka yang hilang adalah 6.'],
['Isi angka yang kosong agar rasionya senilai: 3 : 5 = ___ : 10.',['6'],'Bilangan kedua dikali 2, maka bilangan pertama juga dikali 2: 3 × 2 = 6.'],
['Rasio kelereng Raka terhadap Dito adalah 2 : 1. Jika Raka memiliki 8 kelereng, berapa kelereng Dito?',['4'],'Dari 2 bagian menjadi 8 berarti dikali 4. Satu bagian milik Dito juga dikali 4, jadi 4 kelereng.'],
['Dalam minuman, rasio sirup terhadap air adalah 1 : 4. Jika digunakan 3 gelas sirup, berapa gelas air yang diperlukan?',['12','12 gelas'],'Tiga gelas sirup berarti rasionya dikali 3. Air yang diperlukan 4 × 3 = 12 gelas.'],
['Satu kotak berisi 9 bola kuning dan 6 bola hijau. Sederhanakan rasio bola kuning terhadap seluruh bola.',['3:5','3 : 5'],'Jumlah seluruh bola 9 + 6 = 15. Rasio kuning terhadap seluruh bola adalah 9 : 15, disederhanakan menjadi 3 : 5.']
]}
,{name:'Rasio satuan dalam keseharian',type:'RASIO',desc:'Menentukan nilai per satuan dan menggunakannya dalam soal sehari-hari.',tip:'Cari nilai untuk 1 satuan dengan membagi kedua jumlah menggunakan bilangan yang sama. Setelah mendapat nilai per satuan, kalikan sesuai jumlah yang ditanyakan.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menentukan rasio satuan dan menggunakannya untuk menyelesaikan masalah sehari-hari.</span><b>Petunjuk Konsep</b><span>Rasio satuan menunjukkan banyaknya sesuatu untuk setiap 1 satuan pembanding. Caranya, bagilah kedua jumlah sampai pembandingnya menjadi 1.</span><small>Contoh: 12 jeruk dimasukkan sama rata ke 3 kantong. Karena 12 ÷ 3 = 4, rasio satuannya adalah 4 jeruk per kantong.</small>',qs:[
['Ada 12 pensil yang dibagikan sama rata ke dalam 3 kotak. Berapa pensil per kotak?',['4','4 pensil'],'Hitung 12 ÷ 3 = 4. Jadi setiap kotak berisi 4 pensil.'],
['Dina membaca 20 halaman dalam 4 menit dengan kecepatan tetap. Berapa halaman yang dibaca per menit?',['5','5 halaman'],'Hitung 20 ÷ 4 = 5. Rasio satuannya adalah 5 halaman per menit.'],
['Harga 3 buku tulis adalah Rp15.000. Berapa harga satu buku tulis?',['5000','5.000','rp5000','rp5.000'],'Hitung Rp15.000 ÷ 3 = Rp5.000. Jadi harga satu buku tulis adalah Rp5.000.'],
['Sebanyak 24 kue diletakkan sama rata pada 6 piring. Berapa kue per piring?',['4','4 kue'],'Hitung 24 ÷ 6 = 4. Jadi setiap piring berisi 4 kue.'],
['Tiga wadah menampung total 18 liter air dengan isi sama banyak. Berapa liter air dalam satu wadah?',['6','6 liter'],'Hitung 18 ÷ 3 = 6. Setiap wadah berisi 6 liter air.'],
['Sebuah mesin mencetak 35 kartu dalam 5 menit dengan kecepatan tetap. Berapa kartu yang dicetak per menit?',['7','7 kartu'],'Hitung 35 ÷ 5 = 7. Mesin mencetak 7 kartu per menit.'],
['Empat baki memuat 28 bibit dengan jumlah sama. Jika tersedia 6 baki, berapa bibit yang dapat dimuat dengan rasio yang sama?',['42','42 bibit'],'Mula-mula cari rasio satuan: 28 ÷ 4 = 7 bibit per baki. Untuk 6 baki: 7 × 6 = 42 bibit.'],
['Sebuah mobil menempuh 72 km dalam 3 jam dengan kecepatan tetap. Berapa kilometer jarak yang ditempuh dalam 5 jam?',['120','120 km','120 kilometer'],'Rasio satuannya 72 ÷ 3 = 24 km per jam. Dalam 5 jam, jaraknya 24 × 5 = 120 km.'],
['Untuk membuat 4 teko minuman diperlukan 12 sendok sirup. Berapa sendok sirup untuk membuat 7 teko dengan rasa yang sama?',['21','21 sendok'],'Rasio satuannya 12 ÷ 4 = 3 sendok per teko. Untuk 7 teko diperlukan 3 × 7 = 21 sendok.'],
['Delapan ayam membutuhkan 16 cangkir pakan per hari dengan bagian sama. Berapa cangkir pakan untuk 12 ayam?',['24','24 cangkir'],'Setiap ayam mendapat 16 ÷ 8 = 2 cangkir. Untuk 12 ayam diperlukan 2 × 12 = 24 cangkir.']
]}
,{name:'Proporsi dan tabel rasio',type:'PROPORSI',desc:'Melengkapi rasio senilai dan menyelesaikan masalah proporsi sederhana.',tip:'Cari hubungan pengalinya pada kedua baris tabel. Jika pengali tidak langsung terlihat, temukan nilai per satuan terlebih dahulu, lalu kalikan dengan jumlah yang ditanyakan.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat melengkapi tabel rasio senilai dan menyelesaikan masalah proporsi dengan perkalian atau pembagian.</span><b>Petunjuk Konsep</b><span>Dua rasio disebut senilai jika kedua bilangannya berubah dengan faktor pengali yang sama. Kita dapat memakai faktor pengali atau mencari nilai per satuan.</span><small>Contoh: 2 buku berharga Rp6.000. Karena 6.000 ÷ 2 = 3.000, maka 5 buku berharga 5 × Rp3.000 = Rp15.000.</small>',qs:[
['Dua pensil berharga Rp6.000. Jika harga tiap pensil sama, berapa harga 5 pensil?',['15000','15.000','rp15000','rp15.000'],'Harga satu pensil Rp6.000 ÷ 2 = Rp3.000. Harga 5 pensil adalah 5 × Rp3.000 = Rp15.000.'],
['Tiga botol berisi total 6 liter air. Dengan ukuran botol yang sama, berapa liter air dalam 7 botol?',['14','14 liter'],'Setiap botol berisi 6 ÷ 3 = 2 liter. Jadi 7 botol berisi 7 × 2 = 14 liter.'],
['Rasio manik-manik merah terhadap biru adalah 4 : 6. Jika ada 12 manik-manik merah, berapa manik-manik biru agar rasionya tetap sama?',['18','18 manik-manik'],'Dari 4 menjadi 12 dikali 3. Maka 6 juga dikali 3 sehingga manik-manik biru berjumlah 18.'],
['Lengkapi tabel rasio berikut: 3 mangga seharga Rp12.000, 6 mangga seharga Rp24.000, dan 9 mangga seharga ___.',['36000','36.000','rp36000','rp36.000'],'Harga satu mangga Rp12.000 ÷ 3 = Rp4.000. Jadi 9 mangga berharga 9 × Rp4.000 = Rp36.000.'],
['Lima mobil mainan membutuhkan 20 roda. Berapa roda yang dibutuhkan untuk 8 mobil mainan sejenis?',['32','32 roda'],'Setiap mobil membutuhkan 20 ÷ 5 = 4 roda. Delapan mobil membutuhkan 8 × 4 = 32 roda.'],
['Dua cangkir tepung dapat membuat 8 kue. Berapa cangkir tepung diperlukan untuk membuat 20 kue dengan resep yang sama?',['5','5 cangkir'],'Dua cangkir untuk 8 kue berarti 1 cangkir untuk 4 kue. Untuk 20 kue diperlukan 20 ÷ 4 = 5 cangkir.'],
['Enam meter pita berharga Rp18.000. Berapa harga 10 meter pita dengan harga per meter yang sama?',['30000','30.000','rp30000','rp30.000'],'Harga per meter Rp18.000 ÷ 6 = Rp3.000. Harga 10 meter adalah 10 × Rp3.000 = Rp30.000.'],
['Seorang pesepeda menempuh 28 km dalam 4 jam dengan kecepatan tetap. Berapa kilometer yang ditempuh dalam 6 jam?',['42','42 km','42 kilometer'],'Jarak per jam 28 ÷ 4 = 7 km. Dalam 6 jam, jaraknya 6 × 7 = 42 km.'],
['Lima kantong pupuk cukup untuk lahan seluas 100 m². Jika pemakaiannya sama, berapa luas lahan yang dapat diberi pupuk dengan 7 kantong?',['140','140 m2','140 m²'],'Setiap kantong cukup untuk 100 ÷ 5 = 20 m². Tujuh kantong cukup untuk 7 × 20 = 140 m².'],
['Toko A menjual 4 penghapus seharga Rp8.000. Toko B menjual 6 penghapus seharga Rp15.000. Toko mana yang lebih murah untuk setiap penghapus?',['toko a','a'],'Harga satu penghapus di Toko A Rp2.000, sedangkan di Toko B Rp2.500. Jadi Toko A lebih murah.']
]}
,{name:'Keliling bangun datar',type:'GEOMETRI',desc:'Menghitung keliling persegi, persegi panjang, segitiga, dan bangun bersisi lainnya.',tip:'Keliling adalah jumlah panjang seluruh sisi luar bangun. Persegi: K = 4 × sisi. Persegi panjang: K = 2 × (panjang + lebar).',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menghitung keliling beberapa bangun datar dan menemukan panjang sisi yang belum diketahui.</span><b>Petunjuk Konsep</b><span>Telusuri garis terluar bangun, lalu jumlahkan semua panjang sisinya. Pastikan semua ukuran memakai satuan yang sama.</span><small>Contoh: persegi panjang dengan panjang 8 cm dan lebar 5 cm memiliki keliling 2 × (8 + 5) = 26 cm.</small>',qs:[
['Sebuah persegi memiliki panjang sisi 7 cm. Berapa kelilingnya?',['28','28 cm'],'Keliling persegi adalah 4 × sisi, jadi 4 × 7 = 28 cm.'],
['Sebuah persegi panjang memiliki panjang 12 cm dan lebar 5 cm. Berapa kelilingnya?',['34','34 cm'],'Kelilingnya 2 × (12 + 5) = 2 × 17 = 34 cm.'],
['Sebuah segitiga memiliki panjang sisi 8 cm, 7 cm, dan 9 cm. Berapa kelilingnya?',['24','24 cm'],'Jumlahkan ketiga sisinya: 8 + 7 + 9 = 24 cm.'],
['Sebuah segi lima beraturan memiliki panjang setiap sisi 6 cm. Berapa kelilingnya?',['30','30 cm'],'Segi lima memiliki 5 sisi sama panjang, jadi kelilingnya 5 × 6 = 30 cm.'],
['Taman berbentuk persegi panjang memiliki panjang 15 m dan lebar 8 m. Berapa meter pagar yang diperlukan untuk mengelilinginya satu kali?',['46','46 m','46 meter'],'Panjang pagar sama dengan keliling taman: 2 × (15 + 8) = 46 m.'],
['Keliling sebuah persegi adalah 36 cm. Berapa panjang satu sisinya?',['9','9 cm'],'Panjang sisi persegi adalah keliling ÷ 4, jadi 36 ÷ 4 = 9 cm.'],
['Keliling sebuah persegi panjang adalah 30 cm. Jika panjangnya 9 cm, berapa lebarnya?',['6','6 cm'],'Setengah keliling adalah 30 ÷ 2 = 15 cm. Lebarnya 15 − 9 = 6 cm.'],
['Keliling sebuah segitiga adalah 32 cm. Dua sisinya masing-masing 10 cm dan 11 cm. Berapa panjang sisi ketiga?',['11','11 cm'],'Sisi ketiga adalah 32 − 10 − 11 = 11 cm.'],
['Lapangan berbentuk persegi panjang berukuran 20 m × 12 m. Rani berjalan mengelilinginya dua kali. Berapa meter jarak yang ditempuh Rani?',['128','128 m','128 meter'],'Keliling lapangan 2 × (20 + 12) = 64 m. Dua putaran adalah 2 × 64 = 128 m.'],
['Sebuah bangun memiliki enam sisi luar dengan panjang 8 cm, 3 cm, 3 cm, 4 cm, 5 cm, dan 7 cm. Berapa keliling bangun tersebut?',['30','30 cm'],'Jumlahkan seluruh sisi luar: 8 + 3 + 3 + 4 + 5 + 7 = 30 cm.']
]}
,{name:'Luas persegi & persegi panjang',type:'GEOMETRI',desc:'Menghitung luas persegi dan persegi panjang serta menemukan ukuran sisi yang belum diketahui.',tip:'Luas menyatakan besar daerah yang ditutupi bangun. Persegi: L = sisi × sisi. Persegi panjang: L = panjang × lebar. Gunakan satuan persegi, misalnya cm² atau m².',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menghitung luas persegi dan persegi panjang serta menentukan panjang sisi jika luasnya diketahui.</span><b>Petunjuk Konsep</b><span>Bayangkan bangun ditutup oleh petak satuan tanpa celah. Banyak petak dapat dihitung dengan mengalikan panjang dan lebar. Untuk persegi, panjang dan lebarnya sama.</span><small>Contoh: persegi panjang berukuran 8 cm × 5 cm memiliki luas 8 × 5 = 40 cm².</small>',qs:[
['Sebuah persegi memiliki panjang sisi 6 cm. Berapa luasnya?',['36','36 cm2','36 cm²'],'Luas persegi adalah sisi × sisi, jadi 6 × 6 = 36 cm².'],
['Sebuah persegi panjang memiliki panjang 9 cm dan lebar 4 cm. Berapa luasnya?',['36','36 cm2','36 cm²'],'Luas persegi panjang adalah panjang × lebar, jadi 9 × 4 = 36 cm².'],
['Sebuah persegi memiliki panjang sisi 12 cm. Berapa luasnya?',['144','144 cm2','144 cm²'],'Luasnya 12 × 12 = 144 cm².'],
['Sebuah buku gambar berbentuk persegi panjang dengan panjang 15 cm dan lebar 7 cm. Berapa luas permukaannya?',['105','105 cm2','105 cm²'],'Luas permukaan buku adalah 15 × 7 = 105 cm².'],
['Taman berbentuk persegi panjang berukuran 8 m × 6 m. Berapa luas taman tersebut?',['48','48 m2','48 m²'],'Luas taman adalah 8 × 6 = 48 m².'],
['Luas sebuah persegi panjang adalah 72 cm². Jika panjangnya 9 cm, berapa lebarnya?',['8','8 cm'],'Lebar = luas ÷ panjang, jadi 72 ÷ 9 = 8 cm.'],
['Luas sebuah persegi adalah 81 cm². Berapa panjang sisinya?',['9','9 cm'],'Carilah bilangan yang jika dikalikan dengan dirinya sendiri menghasilkan 81. Karena 9 × 9 = 81, panjang sisinya 9 cm.'],
['Sebuah mozaik berbentuk persegi panjang tersusun dari petak berukuran 1 cm². Jika ada 11 petak pada setiap baris dan 5 baris, berapa luas mozaik?',['55','55 cm2','55 cm²'],'Jumlah petaknya 11 × 5 = 55. Setiap petak luasnya 1 cm², jadi luas mozaik 55 cm².'],
['Taplak meja berbentuk persegi panjang memiliki panjang 120 cm dan lebar 80 cm. Berapa luasnya?',['9600','9.600','9600 cm2','9.600 cm2','9600 cm²','9.600 cm²'],'Luas taplak adalah 120 × 80 = 9.600 cm².'],
['Persegi A memiliki sisi 10 cm. Persegi panjang B berukuran 12 cm × 8 cm. Berapa selisih luas kedua bangun itu?',['4','4 cm2','4 cm²'],'Luas A = 10 × 10 = 100 cm². Luas B = 12 × 8 = 96 cm². Selisihnya 100 − 96 = 4 cm².']
]}
,{name:'Luas segitiga & jajargenjang',type:'GEOMETRI',desc:'Menghitung luas segitiga dan jajargenjang serta menemukan alas atau tinggi yang belum diketahui.',tip:'Segitiga: L = ½ × alas × tinggi. Jajargenjang: L = alas × tinggi. Tinggi harus tegak lurus terhadap alas, bukan sisi miring.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menghitung luas segitiga dan jajargenjang serta menentukan alas atau tinggi jika luasnya diketahui.</span><b>Petunjuk Konsep</b><span>Dua segitiga yang sama dapat disusun menjadi jajargenjang. Karena itu, luas segitiga adalah setengah dari alas × tinggi. Pada jajargenjang, gunakan tinggi yang tegak lurus terhadap alas.</span><small>Contoh: segitiga dengan alas 10 cm dan tinggi 6 cm memiliki luas ½ × 10 × 6 = 30 cm².</small>',qs:[
['Sebuah segitiga memiliki alas 10 cm dan tinggi 6 cm. Berapa luasnya?',['30','30 cm2','30 cm²'],'Luas segitiga = ½ × alas × tinggi = ½ × 10 × 6 = 30 cm².'],
['Sebuah segitiga memiliki alas 14 cm dan tinggi 8 cm. Berapa luasnya?',['56','56 cm2','56 cm²'],'Luasnya ½ × 14 × 8 = 7 × 8 = 56 cm².'],
['Sebuah jajargenjang memiliki alas 9 cm dan tinggi 5 cm. Berapa luasnya?',['45','45 cm2','45 cm²'],'Luas jajargenjang = alas × tinggi, jadi 9 × 5 = 45 cm².'],
['Sebuah jajargenjang memiliki alas 12 cm dan tinggi 7 cm. Berapa luasnya?',['84','84 cm2','84 cm²'],'Luasnya 12 × 7 = 84 cm².'],
['Bendera berbentuk segitiga mempunyai alas 20 cm dan tinggi 12 cm. Berapa luas kain bendera itu?',['120','120 cm2','120 cm²'],'Luas kain = ½ × 20 × 12 = 10 × 12 = 120 cm².'],
['Luas sebuah segitiga adalah 48 cm² dan tingginya 8 cm. Berapa panjang alasnya?',['12','12 cm'],'Alas = 2 × luas ÷ tinggi = 2 × 48 ÷ 8 = 12 cm.'],
['Luas sebuah segitiga adalah 63 cm² dan panjang alasnya 14 cm. Berapa tingginya?',['9','9 cm'],'Tinggi = 2 × luas ÷ alas = 2 × 63 ÷ 14 = 9 cm.'],
['Luas sebuah jajargenjang adalah 96 cm². Jika alasnya 12 cm, berapa tingginya?',['8','8 cm'],'Tinggi = luas ÷ alas = 96 ÷ 12 = 8 cm.'],
['Luas sebuah jajargenjang adalah 72 cm² dan tingginya 6 cm. Berapa panjang alasnya?',['12','12 cm'],'Alas = luas ÷ tinggi = 72 ÷ 6 = 12 cm.'],
['Segitiga A memiliki alas 16 cm dan tinggi 10 cm. Jajargenjang B memiliki alas 9 cm dan tinggi 8 cm. Berapa selisih luas kedua bangun?',['8','8 cm2','8 cm²'],'Luas A = ½ × 16 × 10 = 80 cm². Luas B = 9 × 8 = 72 cm². Selisihnya 80 − 72 = 8 cm².']
]}
,{name:'Luas bangun gabungan',type:'GEOMETRI',desc:'Mengurai bangun gabungan menjadi beberapa bangun sederhana untuk menghitung luas seluruh daerah.',tip:'Pisahkan bangun menjadi persegi panjang, persegi, atau segitiga. Jumlahkan bagian yang digabung; kurangkan bagian yang dipotong atau tidak dihitung.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menghitung luas bangun gabungan dengan cara membagi atau melengkapinya menjadi bangun yang sudah dikenal.</span><b>Petunjuk Konsep</b><span>Tandai setiap bagian, hitung luasnya satu per satu, lalu tentukan apakah harus dijumlahkan atau dikurangkan. Pastikan bagian yang dihitung tidak saling bertumpuk.</span><small>Contoh: bangun terdiri dari persegi panjang 8 cm × 4 cm dan persegi 2 cm × 2 cm yang tidak bertumpuk. Luas total = 32 + 4 = 36 cm².</small>',qs:[
['Sebuah bangun gabungan terdiri dari persegi panjang 8 cm × 4 cm dan persegi panjang 3 cm × 2 cm yang tidak bertumpuk. Berapa luas seluruh bangun?',['38','38 cm2','38 cm²'],'Luas bagian pertama 8 × 4 = 32 cm² dan bagian kedua 3 × 2 = 6 cm². Totalnya 32 + 6 = 38 cm².'],
['Sebuah karton berukuran 12 cm × 7 cm dipotong pada salah satu sudutnya sebesar 4 cm × 3 cm. Berapa luas karton yang tersisa?',['72','72 cm2','72 cm²'],'Luas awal 12 × 7 = 84 cm². Bagian yang dipotong 4 × 3 = 12 cm². Sisanya 84 − 12 = 72 cm².'],
['Gambar rumah tersusun dari persegi panjang 10 cm × 6 cm dan atap segitiga dengan alas 10 cm serta tinggi 4 cm. Berapa luas seluruh gambar?',['80','80 cm2','80 cm²'],'Luas badan rumah 10 × 6 = 60 cm². Luas atap ½ × 10 × 4 = 20 cm². Totalnya 80 cm².'],
['Taman gabungan terdiri dari persegi dengan sisi 9 m dan persegi panjang 6 m × 3 m yang tidak bertumpuk. Berapa luas seluruh taman?',['99','99 m2','99 m²'],'Luas persegi 9 × 9 = 81 m². Luas persegi panjang 6 × 3 = 18 m². Totalnya 81 + 18 = 99 m².'],
['Sebuah bendera terdiri dari persegi panjang 14 cm × 5 cm dan ujung segitiga dengan alas 5 cm serta tinggi 4 cm. Berapa luas bendera?',['80','80 cm2','80 cm²'],'Luas persegi panjang 14 × 5 = 70 cm². Luas segitiga ½ × 5 × 4 = 10 cm². Totalnya 80 cm².'],
['Bangun berbentuk huruf L berasal dari persegi panjang 10 cm × 8 cm yang dipotong persegi panjang 4 cm × 3 cm. Berapa luas bangun L?',['68','68 cm2','68 cm²'],'Luas persegi panjang besar 10 × 8 = 80 cm². Potongannya 4 × 3 = 12 cm². Luas bangun L adalah 80 − 12 = 68 cm².'],
['Lantai berukuran 15 m × 10 m memiliki kolam berukuran 5 m × 4 m. Bagian kolam tidak dipasang ubin. Berapa luas lantai yang dipasang ubin?',['130','130 m2','130 m²'],'Luas lantai 15 × 10 = 150 m². Luas kolam 5 × 4 = 20 m². Daerah berubin 150 − 20 = 130 m².'],
['Sebuah hiasan tersusun dari dua segitiga sama besar. Setiap segitiga memiliki alas 12 cm dan tinggi 7 cm serta tidak bertumpuk. Berapa luas hiasan?',['84','84 cm2','84 cm²'],'Luas satu segitiga ½ × 12 × 7 = 42 cm². Dua segitiga luasnya 2 × 42 = 84 cm².'],
['Panggung terdiri dari persegi panjang 18 m × 8 m dan dua sayap segitiga. Setiap sayap memiliki alas 4 m dan tinggi 3 m. Berapa luas seluruh panggung?',['156','156 m2','156 m²'],'Luas persegi panjang 18 × 8 = 144 m². Dua segitiga luasnya 2 × (½ × 4 × 3) = 12 m². Totalnya 156 m².'],
['Bangun A terdiri dari persegi panjang 8 cm × 6 cm dan segitiga beralas 8 cm serta tinggi 4 cm. Bangun B adalah persegi bersisi 7 cm. Berapa selisih luas A dan B?',['15','15 cm2','15 cm²'],'Luas A = 8 × 6 + ½ × 8 × 4 = 48 + 16 = 64 cm². Luas B = 7 × 7 = 49 cm². Selisihnya 64 − 49 = 15 cm².']
]}
,{name:'Mengenal & mengukur sudut',type:'GEOMETRI',desc:'Mengenali jenis sudut dan menentukan besar sudut dalam derajat pada benda serta putaran sehari-hari.',tip:'Satu putaran penuh = 360°, setengah putaran = 180°, dan seperempat putaran = 90°. Sudut lancip kurang dari 90°, siku-siku tepat 90°, dan tumpul lebih dari 90° tetapi kurang dari 180°.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat mengenali jenis sudut dan menentukan besar sudut sederhana menggunakan satuan derajat.</span><b>Petunjuk Konsep</b><span>Sudut adalah besar bukaan antara dua garis. Saat membaca busur derajat, letakkan titik pusat pada titik sudut dan mulai dari angka 0° pada salah satu kaki sudut.</span><small>Contoh: seperempat putaran membentuk sudut siku-siku sebesar 90°. Pada jam, jarak antara dua angka yang berdekatan adalah 30°.</small>',qs:[
['Berapa derajat besar satu putaran penuh?',['360','360°'],'Satu putaran penuh kembali ke arah awal dan besarnya 360°.'],
['Dua garis saling tegak lurus membentuk sudut jenis apa?',['siku-siku','siku siku'],'Garis yang saling tegak lurus membentuk sudut siku-siku sebesar 90°.'],
['Berapa derajat besar seperempat putaran?',['90','90°'],'Seperempat dari 360° adalah 360° ÷ 4 = 90°.'],
['Sudut sebesar 45° termasuk sudut apa?',['lancip','sudut lancip'],'Sudut lancip besarnya lebih dari 0° dan kurang dari 90°. Karena 45° < 90°, sudut itu lancip.'],
['Sudut sebesar 120° termasuk sudut apa?',['tumpul','sudut tumpul'],'Sudut tumpul lebih dari 90° tetapi kurang dari 180°. Jadi 120° adalah sudut tumpul.'],
['Pada busur derajat, satu kaki sudut berada di 0° dan kaki lainnya menunjuk 70°. Berapa besar sudut itu?',['70','70°'],'Pembacaan dimulai dari 0°. Kaki lainnya menunjuk 70°, sehingga besar sudutnya 70°.'],
['Jarum menit bergerak dari angka 12 ke angka 4. Berapa derajat sudut putarannya?',['120','120°'],'Jarak antarangka pada jam adalah 30°. Dari 12 ke 4 ada 4 langkah, jadi 4 × 30° = 120°.'],
['Berapa derajat besar sudut lurus atau setengah putaran?',['180','180°'],'Setengah dari satu putaran penuh adalah 360° ÷ 2 = 180°.'],
['Sudut A besarnya 35°. Sudut B lebih besar 20° daripada sudut A. Berapa besar sudut B?',['55','55°'],'Besar sudut B = 35° + 20° = 55°.'],
['Jam menunjukkan pukul 02.00. Berapa besar sudut terkecil antara jarum pendek dan jarum panjang?',['60','60°'],'Pada pukul 02.00, jarum panjang di 12 dan jarum pendek di 2. Ada 2 jarak angka, jadi sudutnya 2 × 30° = 60°.']
]}

,{name:'Mengenal kubus & balok',type:'GEOMETRI',desc:'Mengenali unsur, bentuk sisi, dan tampak sederhana pada kubus serta balok.',tip:'Kubus dan balok sama-sama memiliki 6 sisi, 12 rusuk, dan 8 titik sudut. Semua sisi kubus berbentuk persegi, sedangkan sisi balok umumnya berbentuk persegi panjang.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menyebutkan unsur kubus dan balok, membandingkan cirinya, serta mengenali tampak atas atau depan.</span><b>Petunjuk Konsep</b><span>Sisi adalah bidang pembatas, rusuk adalah garis pertemuan dua sisi, dan titik sudut adalah pertemuan beberapa rusuk. Amati benda dari arah yang diminta untuk menentukan bentuk tampaknya.</span><small>Contoh: sebuah kubus memiliki 6 sisi persegi, 12 rusuk, dan 8 titik sudut. Kotak sepatu berbentuk balok; dari atas tampak sebagai persegi panjang.</small>',qs:[
['Berapa banyak sisi yang dimiliki sebuah kubus?',['6','6 sisi'],'Kubus memiliki 6 sisi: atas, bawah, depan, belakang, kiri, dan kanan.'],
['Berapa banyak titik sudut yang dimiliki sebuah kubus?',['8','8 titik sudut'],'Kubus memiliki 8 titik sudut, yaitu titik tempat beberapa rusuk bertemu.'],
['Berapa banyak rusuk yang dimiliki sebuah balok?',['12','12 rusuk'],'Balok memiliki 12 rusuk: 4 di bagian atas, 4 di bagian bawah, dan 4 tegak.'],
['Semua sisi sebuah kubus berbentuk bangun datar apa?',['persegi'],'Keenam sisi kubus berbentuk persegi dan berukuran sama.'],
['Berapa banyak sisi yang dimiliki sebuah balok?',['6','6 sisi'],'Balok memiliki 6 sisi yang tersusun dalam 3 pasang sisi berhadapan.'],
['Ada berapa pasang sisi berhadapan pada balok?',['3','3 pasang'],'Enam sisi balok membentuk 3 pasang sisi berhadapan: atas–bawah, depan–belakang, dan kiri–kanan.'],
['Sebuah kotak berbentuk balok memiliki panjang 8 cm, lebar 5 cm, dan tinggi 4 cm. Ukuran apa yang terlihat dari atas?',['8 cm × 5 cm','8×5','8 x 5','8 cm x 5 cm'],'Tampak atas memperlihatkan panjang dan lebar, yaitu 8 cm × 5 cm. Tinggi tidak terlihat sebagai ukuran bidang atas.'],
['Balok memiliki panjang 10 cm dan tinggi 6 cm. Jika dilihat tepat dari depan, bentuk bidang yang tampak adalah apa?',['persegi panjang'],'Tampak depan balok berbentuk persegi panjang dengan ukuran panjang × tinggi.'],
['Dadu dan kotak tisu masing-masing menyerupai bangun ruang apa?',['kubus dan balok','kubus, balok'],'Dadu menyerupai kubus karena rusuknya sama panjang, sedangkan kotak tisu umumnya menyerupai balok.'],
['Bangun gabungan disusun dari 4 kubus kecil pada baris bawah dan 2 kubus kecil di atasnya. Berapa jumlah seluruh kubus kecil?',['6','6 kubus'],'Jumlahkan semua penyusunnya: 4 + 2 = 6 kubus kecil.']
]}

,{name:'Menyusun & mengurai kubus',type:'GEOMETRI',desc:'Menghitung kubus penyusun, melengkapi bangun, dan membaca tampak atas serta tampak depan.',tip:'Hitung susunan secara teratur: per baris, per lapis, atau per menara. Untuk bangun penuh, banyak kubus = panjang × lebar × tinggi. Pada tampak atas, perhatikan posisi yang terisi; pada tampak depan, perhatikan tinggi tiap menara.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat menyusun dan mengurai bangun ruang dari kubus satuan serta membaca visualisasi sederhana dari arah atas dan depan.</span><b>Petunjuk Konsep</b><span>Kelompokkan kubus agar tidak ada yang dihitung dua kali. Bangun dapat diurai menjadi lapisan atau menara, lalu jumlahkan kubus pada setiap bagian.</span><small>Contoh: alas berisi 3 × 2 kubus dan tingginya 2 lapis. Jumlah kubus = 3 × 2 × 2 = 12.</small>',qs:[
['Tujuh kubus disusun lurus dalam satu baris. Berapa kubus yang terlihat sebagai posisi terisi dari atas?',['7','7 kubus','7 posisi'],'Setiap kubus menempati satu posisi. Karena disusun satu baris tanpa bertumpuk, tampak atas menunjukkan 7 posisi terisi.'],
['Satu lapisan kubus tersusun dalam 3 baris dan setiap baris berisi 2 kubus. Berapa jumlah kubus pada lapisan itu?',['6','6 kubus'],'Jumlah kubus = 3 baris × 2 kubus = 6 kubus.'],
['Sebuah bangun memiliki 2 lapisan. Setiap lapisan terdiri dari 4 kubus. Berapa jumlah seluruh kubus?',['8','8 kubus'],'Ada 2 lapisan dengan 4 kubus per lapisan, jadi 2 × 4 = 8 kubus.'],
['Tiga menara kubus memiliki tinggi 3 kubus, 2 kubus, dan 1 kubus. Berapa jumlah seluruh kubus?',['6','6 kubus'],'Jumlahkan tinggi ketiga menara: 3 + 2 + 1 = 6 kubus.'],
['Alas persegi berukuran 3 × 3 posisi akan diisi penuh dengan satu lapis kubus. Jika sudah ada 7 kubus, berapa kubus lagi yang dibutuhkan?',['2','2 kubus'],'Alas penuh membutuhkan 3 × 3 = 9 kubus. Kekurangannya 9 − 7 = 2 kubus.'],
['Balok padat tersusun dari kubus satuan dengan panjang 4 kubus, lebar 3 kubus, dan tinggi 2 kubus. Berapa kubus satuan penyusunnya?',['24','24 kubus'],'Jumlah kubus satuan = 4 × 3 × 2 = 24 kubus.'],
['Dari depan terlihat tiga menara berdampingan dengan tinggi 2, 1, dan 3 petak. Berapa jumlah petak pada tampak depan?',['6','6 petak'],'Jumlah petak yang terlihat adalah 2 + 1 + 3 = 6 petak.'],
['Sebuah susunan menempati alas 2 baris × 4 kolom tanpa posisi kosong. Berapa posisi yang terlihat pada tampak atas?',['8','8 posisi','8 petak'],'Tampak atas menunjukkan semua posisi alas yang terisi: 2 × 4 = 8 posisi.'],
['Enam persegi sama besar disusun menjadi jaring-jaring yang benar. Jika dilipat, jaring-jaring itu membentuk bangun apa?',['kubus'],'Kubus tersusun dari 6 sisi berbentuk persegi, sehingga jaring-jaring tersebut dapat dilipat menjadi kubus.'],
['Sebuah susunan awalnya terdiri dari 18 kubus kecil. Lima kubus dilepas. Berapa kubus yang masih tersisa?',['13','13 kubus'],'Kurangkan kubus yang dilepas: 18 − 5 = 13 kubus.']
]}
,
{name:'Membaca & menyajikan data dalam tabel',type:'DATA',desc:'Mengelompokkan hasil pengamatan, membaca jumlah, dan menyajikan data sederhana.',tip:'Data mentah dapat dikelompokkan menurut kategori. Catat setiap kategori dan frekuensinya; pastikan jumlah pada tabel sama dengan jumlah seluruh data.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat mengelompokkan data berdasarkan kategori, membaca frekuensi pada tabel, dan menyajikan data sederhana dalam tabel.</span><b>Petunjuk Konsep</b><span>Frekuensi adalah banyaknya data pada setiap kategori. Hitung satu per satu, lalu periksa kembali dengan menjumlahkan semua frekuensi.</span><small>Contoh: data buah apel, pisang, apel, jeruk, apel disajikan sebagai apel 3, pisang 1, dan jeruk 1.</small>',qs:[
['Tabel pilihan olahraga menunjukkan sepak bola 8 siswa, bulu tangkis 5 siswa, dan basket 3 siswa. Olahraga apa yang paling banyak dipilih?',['sepak bola'],'Bandingkan frekuensinya: 8 paling besar, jadi sepak bola paling banyak dipilih.'],
['Tabel pengamatan burung mencatat pipit 6 ekor, merpati 4 ekor, dan kutilang 5 ekor. Berapa jumlah semua burung?',['15','15 ekor'],'Jumlahkan semua frekuensi: 6 + 4 + 5 = 15 ekor.'],
['Pada tabel pilihan permainan, congklak dipilih 9 anak dan lompat tali 6 anak. Berapa selisih jumlah pemilihnya?',['3','3 anak'],'Selisihnya adalah 9 − 6 = 3 anak.'],
['Data warna tas yang terlihat: merah, biru, merah, hijau, biru, merah, kuning, merah. Berapa tas berwarna merah?',['4','4 tas'],'Hitung kemunculan kata merah. Ada 4 tas merah.'],
['Tabel ukuran sepatu mencatat ukuran 30 sebanyak 5 siswa, ukuran 31 sebanyak 7 siswa, dan ukuran 32 sebanyak 3 siswa. Jika 2 siswa baru memakai ukuran 32, berapa frekuensi ukuran 32 sekarang?',['5','5 siswa'],'Frekuensi baru ukuran 32 = 3 + 2 = 5 siswa.'],
['Sajikan data rasa es krim berikut sebagai banyaknya tiap rasa: cokelat, vanila, cokelat, stroberi, vanila, cokelat, stroberi.',['cokelat:3,vanila:2,stroberi:2','cokelat 3, vanila 2, stroberi 2','cokelat 3; vanila 2; stroberi 2'],'Hitung tiap rasa: cokelat muncul 3 kali, vanila 2 kali, dan stroberi 2 kali.'],
['Tabel peminjaman buku mencatat Senin 7 buku, Selasa 12 buku, Rabu 9 buku, dan Kamis 5 buku. Pada hari apa buku paling banyak dipinjam?',['selasa'],'Frekuensi terbesar adalah 12 buku pada hari Selasa.'],
['Data jumlah tanaman di kebun dicatat dalam tabel: mawar 8, melati 6, dan anggrek 4. Berapa tanaman melati dan anggrek jika digabung?',['10','10 tanaman'],'Jumlah melati dan anggrek adalah 6 + 4 = 10 tanaman.'],
['Dalam tabel koleksi kelereng, merah ada 8 dan biru ada 6. Jumlah seluruh kelereng 20. Berapa kelereng hijau?',['6','6 kelereng'],'Jumlah yang sudah diketahui 8 + 6 = 14. Kelereng hijau = 20 − 14 = 6.'],
['Data dikumpulkan berdasarkan warna tas siswa. Kategori apa yang dicatat pada tabel?',['warna','warna tas'],'Data dikelompokkan menurut karakteristik warna, jadi kategori yang dicatat adalah warna tas.']
]}
,
{name:'Membaca diagram gambar (piktogram)',type:'DATA',desc:'Membaca dan membandingkan banyak benda melalui gambar berskala sederhana.',tip:'Perhatikan keterangan nilai setiap simbol. Banyak benda = jumlah simbol × nilai satu simbol.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat membaca jumlah pada piktogram sederhana, membandingkan kategori, dan menentukan banyak simbol atau benda.</span><b>Petunjuk Konsep</b><span>Ikuti kunci piktogram lebih dulu. Jika 1 gambar mewakili 2 benda, maka 5 gambar mewakili 5 × 2 = 10 benda.</span><small>Contoh: ★ = 3 buku. Empat bintang berarti 4 × 3 = 12 buku.</small>',qs:[
['Keterangan 📘 = 2 buku. Piktogram rak A menunjukkan 📘📘📘📘📘📘. Berapa buku di rak A?',['12','12 buku'],'Ada 6 gambar. Setiap gambar mewakili 2 buku, jadi 6 × 2 = 12 buku.'],
['Dalam piktogram, 🍎 mewakili 3 apel. Kelas mengumpulkan 🍎🍎🍎🍎. Berapa apel terkumpul?',['12','12 apel'],'Ada 4 gambar apel. Jadi 4 × 3 = 12 apel.'],
['Keterangan ★ = 2 siswa. Sepak bola ★★★★★ dan bulu tangkis ★★★. Berapa seluruh siswa yang memilih dua olahraga itu?',['16','16 siswa'],'Jumlah simbolnya 5 + 3 = 8. Setiap simbol mewakili 2 siswa, jadi 8 × 2 = 16 siswa.'],
['Keterangan 🪴 = 4 tanaman. Mawar 🪴🪴🪴🪴🪴🪴 dan melati 🪴🪴🪴🪴. Berapa selisih jumlah kedua tanaman?',['8','8 tanaman'],'Selisih simbol 6 − 4 = 2. Setiap simbol mewakili 4 tanaman, jadi selisihnya 2 × 4 = 8 tanaman.'],
['Pada piktogram pilihan kegiatan, 1 gambar mewakili 1 anak. Membaca ada 5 gambar, menggambar 8 gambar, dan menyanyi 6 gambar. Kegiatan mana yang paling banyak dipilih?',['menggambar'],'Jumlah terbesar adalah 8 gambar, yaitu kegiatan menggambar.'],
['Keterangan ★ = 2 kelereng. Merah memiliki 5 gambar, biru 4 gambar, dan seluruh kelereng ada 24. Berapa gambar yang mewakili kelereng hijau?',['3','3 gambar'],'Totalnya 24 ÷ 2 = 12 gambar. Merah dan biru memakai 5 + 4 = 9 gambar, jadi hijau 12 − 9 = 3 gambar.'],
['Satu gambar ✏️ mewakili 3 pensil. Untuk menyajikan 18 pensil, berapa gambar ✏️ yang diperlukan?',['6','6 gambar'],'Banyak gambar adalah 18 ÷ 3 = 6 gambar.'],
['Satu gambar 🐟 mewakili 5 ikan. Piktogram menunjukkan 7 gambar 🐟. Berapa jumlah ikannya?',['35','35 ikan'],'Tujuh gambar mewakili 7 × 5 = 35 ikan.'],
['Keterangan ★ = 2 hewan. Kucing memiliki 4 gambar dan burung 7 gambar. Kategori mana yang jumlahnya 6 hewan lebih banyak?',['burung'],'Selisihnya 7 − 4 = 3 gambar. Tiga gambar mewakili 3 × 2 = 6 hewan, sehingga burung lebih banyak.'],
['Satu lambang 🍐 mewakili 3 buah pir. Jika ada 15 buah pir, berapa lambang 🍐 yang digambar?',['5','5 lambang','5 gambar'],'Bagi jumlah pir dengan nilai setiap lambang: 15 ÷ 3 = 5 lambang.']
]}
,
{name:'Membaca diagram batang sederhana',type:'DATA',desc:'Membaca skala, tinggi batang, dan informasi dari diagram batang sederhana.',tip:'Lihat angka pada sumbu dan perhatikan nilai setiap kotak atau interval sebelum membaca tinggi batang.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat membaca skala diagram batang, membandingkan tinggi batang, dan memakai informasi diagram untuk menjawab pertanyaan.</span><b>Petunjuk Konsep</b><span>Setiap kotak batang dapat mewakili lebih dari satu benda. Kalikan banyak kotak dengan nilai pada keterangan skala. Periksa angka pada sumbu sebelum membandingkan.</span><small>Contoh: jika 1 kotak = 2 buku dan batang memiliki 4 kotak, jumlahnya 4 × 2 = 8 buku.</small>',qs:[
['Diagram jumlah buku (1 kotak = 2 buku): Senin ■■■, Selasa ■■■■■, Rabu ■■. Berapa buku yang dipinjam pada Senin?',['6','6 buku'],'Batang Senin memiliki 3 kotak. Setiap kotak bernilai 2 buku, jadi 3 × 2 = 6 buku.'],
['Diagram pilihan kegiatan (1 kotak = 2 anak): membaca ■■■■, olahraga ■■■■■■, menggambar ■■■. Kegiatan mana yang dipilih paling banyak?',['olahraga'],'Batang olahraga paling panjang, dengan 6 kotak. Jadi olahraga paling banyak dipilih.'],
['Diagram hasil panen (1 kotak = 5 kg): kebun A ■■, B ■■■, C ■■■■. Berapa kg hasil panen kebun C?',['20','20 kg'],'Batang C memiliki 4 kotak. Jadi 4 × 5 = 20 kg.'],
['Pada diagram (1 kotak = 3 siswa), Senin memiliki 4 kotak dan Rabu 7 kotak. Berapa selisih jumlah siswa pada kedua hari?',['9','9 siswa'],'Selisihnya 7 − 4 = 3 kotak. Setiap kotak bernilai 3 siswa, jadi 3 × 3 = 9 siswa.'],
['Diagram penjualan (1 kotak = 4 roti): Jumat ■■■, Sabtu ■■■■, Minggu ■■. Berapa roti terjual selama tiga hari?',['36','36 roti'],'Jumlah kotak 3 + 4 + 2 = 9. Jadi 9 × 4 = 36 roti.'],
['Pada sumbu diagram tertulis 0, 2, 4, 6, 8. Ujung batang berhenti tepat di angka 6. Berapa nilai data batang itu?',['6','6 satuan'],'Baca angka pada sumbu di ujung batang: nilainya 6 satuan.'],
['Diagram (1 kotak = 1 gelas) menunjukkan susu ■■, jus ■■■, dan air ■■■■■. Urutkan minuman dari jumlah paling sedikit ke paling banyak.',['susu,jus,air','susu, jus, air'],'Jumlah kotaknya berturut-turut 2, 3, dan 5. Jadi urutannya susu, jus, lalu air.'],
['Pada diagram jumlah stiker (1 kotak = 1 stiker), kelas A mendapat 4 kotak dan kelas B 6 kotak. Jika jumlah seluruhnya 15 stiker, berapa stiker yang didapat kelas C?',['5','5 stiker'],'Kotak A dan B berjumlah 4 + 6 = 10 stiker. Kelas C mendapat 15 − 10 = 5 stiker.'],
['Diagram (1 kotak = 2 buah) menunjukkan apel ■■■, jeruk ■■■■■, dan pir ■■■■. Pernyataan “jeruk 4 buah lebih banyak daripada apel” benar atau salah?',['benar'],'Selisihnya 5 − 3 = 2 kotak. Dua kotak mewakili 2 × 2 = 4 buah, jadi pernyataan itu benar.'],
['Untuk menggambar batang jumlah 18 pensil dengan skala 1 kotak = 3 pensil, berapa kotak panjang batangnya?',['6','6 kotak'],'Banyak kotak adalah 18 ÷ 3 = 6 kotak.']
]}
,{name:'Menafsirkan data & menarik kesimpulan',type:'DATA',desc:'Menggunakan data untuk membandingkan, menghitung perubahan, dan membuat kesimpulan sederhana.',tip:'Baca judul, label, dan skala. Kesimpulan harus sesuai dengan angka yang benar-benar ditampilkan.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat mengambil informasi dari data, membandingkan nilai, menghitung perubahan, dan memilih kesimpulan yang didukung data.</span><b>Petunjuk Konsep</b><span>Periksa apa yang diukur dan satuannya. Untuk mencari selisih, kurangkan nilai besar dengan nilai kecil. Kesimpulan yang baik tidak boleh melebihi informasi pada data.</span><small>Contoh: data 18, 24, dan 21 menunjukkan nilai tertinggi 24 serta selisih tertinggi dan terendah 6.</small>',qs:[
['Tabel pengunjung perpustakaan: Senin 18 anak, Selasa 24 anak, Rabu 21 anak. Hari apa pengunjung paling banyak?',['Selasa'],'Nilai terbesar adalah 24, sehingga pengunjung paling banyak datang pada Selasa.'],
['Tinggi tanaman: minggu ke-1 = 12 cm, minggu ke-2 = 15 cm, minggu ke-3 = 19 cm. Berapa pertambahan tinggi dari minggu ke-1 ke minggu ke-3?',['7','7 cm'],'Kurangkan tinggi akhir dengan tinggi awal: 19 − 12 = 7 cm.'],
['Peminjaman buku: cerita 8 buku, sains 12 buku, komik 10 buku. Berapa selisih buku sains dan komik?',['2','2 buku'],'Buku sains 12 dan komik 10. Selisihnya 12 − 10 = 2 buku.'],
['Sampah daur ulang: kelas A 14 kg, kelas B 18 kg, kelas C 16 kg. Berapa kg jumlah seluruhnya?',['48','48 kg'],'Jumlahkan semua data: 14 + 18 + 16 = 48 kg.'],
['Suhu udara: pagi 25°C, siang 31°C, malam 27°C. Berapa kenaikan suhu dari pagi ke siang?',['6','6°C','6 °C'],'Suhu naik dari 25°C menjadi 31°C. Kenaikannya 31 − 25 = 6°C.'],
['Cara berangkat ke sekolah: berjalan 9 anak, bersepeda 6 anak, naik mobil 5 anak. Berapa anak lebih banyak yang berjalan daripada naik mobil?',['4','4 anak'],'Bandingkan 9 anak dan 5 anak. Selisihnya 9 − 5 = 4 anak.'],
['Air yang diminum: Senin 6 gelas, Selasa 8 gelas, Rabu 8 gelas, Kamis 10 gelas. Apakah jumlah pada Selasa dan Rabu berubah? Jawab ya atau tidak.',['tidak'],'Selasa dan Rabu sama-sama 8 gelas, sehingga jumlahnya tidak berubah.'],
['Penjualan pita: merah 5 gulung, biru 9 gulung, kuning 6 gulung. Pernyataan “pita biru paling banyak dan pita merah paling sedikit” benar atau salah?',['benar'],'Nilai terbesar adalah biru, 9 gulung, sedangkan nilai terkecil adalah merah, 5 gulung. Pernyataan itu benar.'],
['Waktu membaca: Ani 25 menit, Budi 30 menit, Citra 20 menit, Deni 30 menit. Siapa dua anak dengan waktu membaca paling lama?',['Budi dan Deni','Budi,Deni','Deni dan Budi','Deni,Budi'],'Waktu terlama adalah 30 menit dan dicapai oleh Budi serta Deni.'],
['Pilihan camilan: roti 12 anak, buah 15 anak, puding 8 anak. Bolehkah disimpulkan bahwa semua anak memilih buah? Jawab ya atau tidak.',['tidak'],'Tidak. Buah memang paling banyak dipilih, tetapi hanya 15 anak; data juga menunjukkan ada anak yang memilih roti dan puding.']
]}

,{name:'Peluang kejadian sederhana',type:'PELUANG',desc:'Mengenali kejadian pasti, mungkin, dan tidak mungkin serta membandingkan kemungkinan.',tip:'Lihat semua hasil yang dapat terjadi. Semakin banyak hasil yang mendukung suatu kejadian, semakin besar kemungkinannya.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat mengelompokkan kejadian sebagai pasti, mungkin, atau tidak mungkin dan membandingkan dua kemungkinan sederhana.</span><b>Petunjuk Konsep</b><span>Kejadian pasti selalu terjadi, kejadian mungkin dapat terjadi tetapi tidak selalu, dan kejadian tidak mungkin tidak dapat terjadi. Jika pilihan sejenis lebih banyak, peluang terpilihnya juga lebih besar.</span><small>Contoh: dalam kantong berisi 4 kelereng merah dan 1 biru, mengambil merah lebih mungkin daripada mengambil biru.</small>',qs:[
['Sebuah kantong hanya berisi 5 kelereng merah. Mengambil kelereng biru merupakan kejadian apa?',['tidak mungkin'],'Tidak ada kelereng biru di dalam kantong, sehingga kejadian itu tidak mungkin.'],
['Sebuah dadu memiliki angka 1 sampai 6. Mendapat angka kurang dari 7 merupakan kejadian apa?',['pasti'],'Semua sisi dadu bernilai kurang dari 7, sehingga kejadian itu pasti.'],
['Satu koin dilempar sekali. Mendapat sisi gambar merupakan kejadian apa?',['mungkin'],'Koin dapat menunjukkan sisi gambar atau sisi angka. Jadi sisi gambar mungkin muncul, tetapi tidak pasti.'],
['Kotak berisi 6 pensil merah dan 2 pensil hijau. Warna apa yang lebih mungkin terambil tanpa melihat?',['merah','pensil merah'],'Pensil merah berjumlah 6, lebih banyak daripada pensil hijau yang berjumlah 2. Jadi merah lebih mungkin terambil.'],
['Kartu bernomor 1 sampai 10 diambil satu. Mana yang lebih mungkin: mendapat bilangan genap atau mendapat bilangan lebih dari 8?',['bilangan genap','genap'],'Ada 5 bilangan genap, yaitu 2, 4, 6, 8, 10, sedangkan bilangan lebih dari 8 hanya 9 dan 10. Jadi bilangan genap lebih mungkin.'],
['Pemutar memiliki 4 bagian sama besar: 2 kuning, 1 merah, dan 1 biru. Apakah merah dan biru memiliki kemungkinan yang sama? Jawab ya atau tidak.',['ya'],'Merah dan biru masing-masing menempati 1 dari 4 bagian yang sama besar, sehingga kemungkinannya sama.'],
['Di dalam kotak ada 6 bola biru, 3 bola kuning, dan 1 bola merah. Warna apa yang paling kecil kemungkinannya terambil?',['merah','bola merah'],'Bola merah hanya 1, paling sedikit dibandingkan warna lain. Jadi merah paling kecil kemungkinannya.'],
['Besok Hanum akan sarapan. Kejadian “Hanum sarapan nasi” termasuk pasti, mungkin, atau tidak mungkin?',['mungkin'],'Hanum dapat memilih nasi atau makanan lain. Sarapan nasi dapat terjadi, tetapi tidak selalu terjadi.'],
['Kartu huruf A, I, U, E, dan O dimasukkan ke kotak. Mengambil huruf vokal merupakan kejadian apa?',['pasti'],'Semua kartu berisi huruf vokal, sehingga kartu apa pun yang terambil pasti huruf vokal.'],
['Urutkan tingkat kemungkinan dari paling kecil ke paling besar: pasti, tidak mungkin, mungkin.',['tidak mungkin,mungkin,pasti','tidak mungkin, mungkin, pasti'],'Urutan dari peluang paling kecil adalah tidak mungkin, kemudian mungkin, lalu pasti.']
]}

,{name:'Percobaan peluang & frekuensi hasil',type:'PELUANG',desc:'Mencatat hasil percobaan sederhana, membandingkan frekuensi, dan membuat perkiraan.',tip:'Frekuensi adalah banyaknya suatu hasil muncul. Hasil yang paling sering muncul pada percobaan belum tentu selalu muncul berikutnya.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat membaca catatan hasil percobaan peluang, menghitung frekuensi, membandingkan hasil, dan membuat perkiraan sederhana.</span><b>Petunjuk Konsep</b><span>Lakukan percobaan berulang, catat setiap hasil, lalu hitung banyak kemunculannya. Jumlah seluruh frekuensi harus sama dengan banyak percobaan.</span><small>Contoh: koin dilempar 10 kali dan muncul gambar 6 kali serta angka 4 kali. Frekuensi gambar = 6, tetapi lemparan berikutnya tetap belum dapat dipastikan.</small>',qs:[
['Koin dilempar 10 kali. Sisi gambar muncul 6 kali dan sisi angka 4 kali. Berapa jumlah seluruh percobaan?',['10','10 kali'],'Jumlah frekuensinya 6 + 4 = 10, sama dengan banyak percobaan.'],
['Pada percobaan koin yang sama, sisi mana yang lebih sering muncul?',['gambar','sisi gambar'],'Gambar muncul 6 kali, lebih banyak daripada angka yang muncul 4 kali.'],
['Gambar muncul 6 kali dan angka 4 kali. Berapa selisih frekuensi kedua hasil itu?',['2','2 kali'],'Selisih frekuensinya adalah 6 − 4 = 2 kali.'],
['Pemutar warna diputar 20 kali. Hasilnya merah 8 kali, biru 5 kali, dan hijau 7 kali. Warna apa yang paling sering muncul?',['merah'],'Merah memiliki frekuensi terbesar, yaitu 8 kali.'],
['Urutkan hasil pemutar dari frekuensi paling kecil ke paling besar: merah 8, biru 5, hijau 7.',['biru,hijau,merah','biru, hijau, merah'],'Frekuensinya 5, 7, dan 8. Jadi urutannya biru, hijau, lalu merah.'],
['Dadu dilempar 12 kali. Bilangan genap muncul 7 kali dan ganjil 5 kali. Berapa kali bilangan genap muncul?',['7','7 kali'],'Catatan percobaan menunjukkan bilangan genap muncul sebanyak 7 kali.'],
['Karena bilangan genap lebih sering muncul pada 12 lemparan sebelumnya, apakah lemparan berikutnya pasti genap? Jawab ya atau tidak.',['tidak'],'Tidak. Hasil percobaan sebelumnya membantu membuat perkiraan, tetapi hasil lemparan berikutnya tidak dapat dipastikan.'],
['Bola diambil lalu dikembalikan ke kantong sebanyak 12 kali. Kuning muncul 9 kali dan hijau 3 kali. Berdasarkan percobaan, warna mana yang lebih mungkin muncul?',['kuning','bola kuning'],'Kuning muncul 9 kali, lebih sering daripada hijau yang muncul 3 kali. Berdasarkan percobaan, kuning lebih mungkin.'],
['Kartu bintang muncul 12 kali dari 20 pengambilan. Tuliskan frekuensi bintang dalam bentuk “... dari ...”.',['12 dari 20','12/20'],'Bintang tercatat muncul 12 kali dalam total 20 pengambilan, jadi frekuensinya 12 dari 20.'],
['Kelompok A memutar pemutar 10 kali dan mendapat merah 6 kali. Kelompok B mendapat merah 4 kali. Apakah hasil berbeda berarti salah satu kelompok pasti keliru? Jawab ya atau tidak.',['tidak'],'Tidak. Percobaan peluang dapat menghasilkan frekuensi berbeda meskipun alat dan jumlah percobaannya sama.']
]}

,{name:'Pengulangan akhir semester',type:'CAMPURAN',desc:'Meninjau kembali konsep penting semester ini melalui soal campuran.',tip:'Baca setiap soal lalu tentukan konsepnya lebih dahulu. Kerjakan dengan langkah singkat dan periksa satuan jawaban.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat memilih dan menggunakan konsep yang tepat untuk menyelesaikan soal campuran dari berbagai materi semester ini.</span><b>Petunjuk Konsep</b><span>Tandai kata kunci: pembagian sama rata memakai FPB, kejadian berulang memakai KPK, pecahan perlu penyebut yang sesuai, dan soal bangun datar harus memakai rumus serta satuan.</span><small>Contoh: sebelum menghitung, tulis dulu “konsep: keliling” atau “konsep: pecahan” agar tidak salah memilih cara.</small>',qs:[
['Ada 18 pensil merah dan 30 pensil biru yang akan dibagi menjadi paket sama lengkap sebanyak mungkin. Berapa paket dapat dibuat?',['6','6 paket'],'Cari FPB(18, 30). Faktor persekutuan terbesarnya 6, jadi dapat dibuat 6 paket.'],
['Alarm A berbunyi setiap 8 menit dan alarm B setiap 12 menit. Keduanya berbunyi pukul 07.30. Pukul berapa keduanya berbunyi bersama lagi?',['07:54','07.54','7:54','7.54'],'KPK(8, 12) = 24 menit. Pukul 07.30 ditambah 24 menit menjadi 07.54.'],
['Manakah yang lebih besar, 5/6 atau 7/9?',['5/6'],'Samakan penyebut menjadi 18: 5/6 = 15/18 dan 7/9 = 14/18. Jadi 5/6 lebih besar.'],
['Hitung 3/4 + 2/3.',['1 5/12','17/12'],'Samakan penyebut menjadi 12: 3/4 = 9/12 dan 2/3 = 8/12. Jumlahnya 17/12 = 1 5/12.'],
['Urutkan dari terkecil ke terbesar dengan tanda <: 0,42; 0,4; 0,405.',['0,4<0,405<0,42'],'Tulis dengan jumlah angka desimal sama: 0,400; 0,405; 0,420. Jadi 0,4 < 0,405 < 0,42.'],
['Lanjutkan pola berikut: 7, 12, 17, 22, ___.',['27'],'Setiap suku bertambah 5. Jadi 22 + 5 = 27.'],
['Rasio anak laki-laki dan perempuan adalah 3 : 5. Jika ada 12 anak laki-laki, berapa anak perempuan?',['20','20 anak'],'Dari 3 bagian menjadi 12 berarti dikali 4. Maka 5 bagian × 4 = 20 anak perempuan.'],
['Persegi panjang memiliki panjang 11 cm dan lebar 7 cm. Berapa kelilingnya?',['36','36 cm'],'Keliling = 2 × (panjang + lebar) = 2 × (11 + 7) = 36 cm.'],
['Sebuah sudut besarnya 135°. Termasuk sudut apakah itu?',['tumpul','sudut tumpul'],'Sudut 135° lebih dari 90° dan kurang dari 180°, sehingga termasuk sudut tumpul.'],
['Hasil pilihan buah: apel 14 anak, jeruk 9 anak, pisang 7 anak. Jika satu pilihan diambil secara acak dari catatan itu, buah apa yang paling mungkin terambil?',['apel'],'Apel memiliki frekuensi terbesar, yaitu 14. Karena itu apel paling mungkin terambil.']
]}

,{name:'Bilangan cacah sampai 1.000.000',type:'BILANGAN',desc:'Membaca, menulis, mengurai, membandingkan, dan menentukan nilai tempat bilangan cacah.',tip:'Baca bilangan dari kelompok terbesar. Nilai sebuah angka ditentukan oleh posisinya: satuan, puluhan, ratusan, ribuan, puluh ribuan, atau ratus ribuan.',lessonNote:'<b>Tujuan Belajar</b><span>Hanum dapat membaca, menulis, mengurai, membandingkan, dan menentukan nilai tempat bilangan cacah sampai 1.000.000.</span><b>Petunjuk Konsep</b><span>Pisahkan bilangan menjadi kelompok ribuan agar mudah dibaca. Perhatikan posisi setiap angka dari kanan: satuan, puluhan, ratusan, ribuan, puluh ribuan, lalu ratus ribuan.</span><small>Contoh: 425.306 dibaca empat ratus dua puluh lima ribu tiga ratus enam dan dapat diurai menjadi 400.000 + 20.000 + 5.000 + 300 + 6.</small>',qs:[
['Tuliskan dengan angka: tiga ratus dua puluh empat ribu seratus lima.',['324.105','324105'],'Tiga ratus dua puluh empat ribu = 324.000, lalu ditambah 105 menjadi 324.105.'],
['Bagaimana cara membaca bilangan 507.042?',['lima ratus tujuh ribu empat puluh dua'],'Kelompok ribuannya 507 ribu dan kelompok satuannya 42, sehingga dibaca lima ratus tujuh ribu empat puluh dua.'],
['Pada bilangan 682.451, angka 8 menempati nilai tempat apa?',['puluh ribuan'],'Dari kanan, angka 8 berada pada posisi puluh ribuan. Nilainya 80.000.'],
['Berapa nilai angka 7 pada bilangan 375.204?',['70.000','70000'],'Angka 7 berada pada tempat puluh ribuan, sehingga nilainya 70.000.'],
['Uraikan bilangan 406.219 menjadi bentuk panjang.',['400.000+6.000+200+10+9','400000+6000+200+10+9'],'Nilai setiap angka bukan nol adalah 400.000, 6.000, 200, 10, dan 9.'],
['Susun menjadi bilangan: 700.000 + 40.000 + 2.000 + 500 + 8.',['742.508','742508'],'Gabungkan semua nilai tempat: 700.000 + 40.000 + 2.000 + 500 + 8 = 742.508.'],
['Isi tanda yang tepat: 598.765 ___ 598.675.',['>'],'Angka ratus ribu, puluh ribu, dan ribunya sama. Pada tempat ratusan, 7 lebih besar daripada 6, jadi 598.765 > 598.675.'],
['Urutkan dari terkecil ke terbesar: 210.045, 201.450, 210.405.',['201.450,210.045,210.405','201450,210045,210405'],'201.450 paling kecil. Di antara dua bilangan 210 ribu, 210.045 lebih kecil daripada 210.405.'],
['Bilangan berapakah yang nilainya 1 lebih besar daripada 999.999?',['1.000.000','1000000'],'Menambahkan 1 pada 999.999 menghasilkan 1.000.000.'],
['Perpustakaan memiliki 125.480 buku, lalu menerima 10.000 buku baru. Berapa jumlah bukunya sekarang?',['135.480','135480','135.480 buku'],'Menambahkan 10.000 menaikkan angka pada tempat puluh ribuan: 125.480 + 10.000 = 135.480 buku.']
]}

];
const modules=[
  {title:'Bilangan dan operasi hitung',detail:'Bilangan cacah, nilai tempat, dan operasi · 1 sesi tersedia',state:'Sedang dipelajari',active:true,start:33,end:34},
  {title:'Faktor, FPB, dan KPK',detail:'Faktor, FPB, KPK, dan tantangan expert',state:'Latihan tersedia',start:0,end:8},
  {title:'Pecahan dan desimal',detail:'Pecahan, operasi, hubungan, dan urutan desimal',state:'Latihan tersedia',start:8,end:15},
  {title:'Pola bilangan dan perbandingan',detail:'Pola, rasio sederhana, rasio satuan, dan proporsi',state:'Latihan tersedia',start:15,end:19},
  {title:'Pengukuran dan geometri',detail:'Sudut, luas, keliling, dan bangun ruang',state:'Latihan tersedia',start:19,end:26},
  {title:'Data, peluang, dan pengulangan',detail:'Data, peluang, dan pengulangan campuran · 7 sesi tersedia',state:'Latihan tersedia',start:26,end:33}
];
const STORE='belajarBarengHanum.v1';
const $=id=>document.getElementById(id);
const clean=s=>String(s).toLowerCase().replace(/[\s.]/g,'').replace(/，/g,',');
const answerMatches=(input,expected)=>{
  const options=Array.isArray(expected)?expected:[expected];
  return options.some(option=>clean(option)===clean(input||''));
};
const answerLabel=expected=>Array.isArray(expected)?expected[0]:expected;
let saved={};
try{saved=JSON.parse(localStorage.getItem(STORE)||'{}')||{};}catch(_){saved={};}
const migrateOldScores=!Array.isArray(saved.records);
saved.records=Array.isArray(saved.records)?saved.records:[];
if(migrateOldScores){
  Object.entries(saved.days||{}).forEach(([day,state])=>{
    if(state?.checked&&Number.isFinite(Number(state.score)))saved.records.push({day:Number(day),score:Number(state.score),total:10,timestamp:null,legacy:true});
  });
  try{localStorage.setItem(STORE,JSON.stringify(saved));}catch(_){/* local storage may be disabled */}
}
let current=Math.min(Math.max(Number(saved.current)||0,0),lessons.length-1);
let checked=Boolean(saved.days?.[current]?.checked);
let answers=Array.isArray(saved.days?.[current]?.answers)?saved.days[current].answers:Array(10).fill('');
function persist(){
  saved.current=current;
  saved.days=saved.days||{};
  saved.days[current]={answers,checked,score:checked?scoreDay():null};
  try{localStorage.setItem(STORE,JSON.stringify(saved));}catch(_){/* local storage may be disabled */}
  renderSemester();
}
function scoreDay(){return lessons[current].qs.reduce((n,q,i)=>n+(answerMatches(answers[i],q[1])?1:0),0);}
function renderSemester(){
  const done=lessons.reduce((n,_,i)=>n+(saved.days?.[i]?.checked?1:0),0);
  $('semester-status').textContent=`${done} dari ${lessons.length} hari selesai`;
  $('semester-modules').innerHTML=modules.map((m,i)=>{
    const count=Math.max(0,Math.min(m.end,lessons.length)-Math.min(m.start,lessons.length));
    const groupLabel=count?`Menuju ${m.title}, kelompok ${count} sesi latihan`:`Menuju kelompok ${m.title}, latihan belum tersedia`;
    return `<a class="module-card module-link ${m.active?'module-active':''} ${count?'':'module-upcoming'}" href="#lesson-group-${i+1}" aria-label="${groupLabel}"><span class="module-index">${String(i+1).padStart(2,'0')}</span><div class="module-copy"><b>${m.title}</b><small>${m.detail}</small></div><span class="module-state">${count?`${count} SESI · KLIK UNTUK BUKA`:m.state.toUpperCase()}</span></a>`;
  }).join('');
}
function renderHistory(){
  const records=Array.isArray(saved.records)?saved.records:[];
  $('history-total').textContent=`${records.length} ${records.length===1?'percobaan':'percobaan'}`;
  if(!records.length){$('score-history').innerHTML='<p class="history-empty">Belum ada nilai. Setelah Hanum menyelesaikan dan memeriksa satu latihan, hasilnya akan muncul di sini.</p>';return;}
  const formatDate=stamp=>{
    if(!stamp)return 'Nilai lama · waktu tidak tercatat';
    const date=new Date(stamp);if(Number.isNaN(date.getTime()))return 'Waktu tidak tersedia';
    return new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(date)+' WIB';
  };
  const sorted=[...records].sort((a,b)=>new Date(b.timestamp||0)-new Date(a.timestamp||0));
  $('score-history').innerHTML=sorted.map(record=>{
    const lesson=lessons[Number(record.day)];const title=lesson?.name||'Latihan Matematika';
    return `<article class="score-row"><div class="score-session"><b>${escapeHtml(title)}</b><small>${formatDate(record.timestamp)}</small></div><div class="score-value"><b>${Number(record.score)||0}<span>/${Number(record.total)||10}</span></b><small>nilai</small></div></article>`;
  }).join('');
}
function renderDays(){
  $('day-list').innerHTML=modules.map((m,mi)=>{
    const entries=lessons.map((lesson,index)=>({lesson,index})).filter(({index})=>index>=m.start&&index<m.end);
    const body=entries.length?entries.map(({lesson:d,index:i})=>{
      const done=Boolean(saved.days?.[i]?.checked);
      return `<button class="day-button ${i===current?'active':''} ${done?'done':''} ${d.type==='EXPERT'?'expert-button':''}" data-day="${i}" aria-pressed="${i===current}"><span class="day-number">${done?'✓':String(i+1).padStart(2,'0')}</span><span><span class="day-name">${d.name}</span><span class="day-sub">10 soal · ${d.type.toLowerCase()}${done?` · nilai ${saved.days[i].score}/10`:''}</span></span><span class="day-mark">${done?'✓':''}</span></button>`;
    }).join(''):`<p class="group-empty">Latihan untuk kategori ini belum tersedia. Materi ini ada di peta belajar.</p>`;
    return `<section class="lesson-group" id="lesson-group-${mi+1}" aria-labelledby="lesson-group-title-${mi+1}"><div class="lesson-group-heading"><b id="lesson-group-title-${mi+1}">${m.title}</b><span>${entries.length?`${entries.length} sesi latihan`:'Belum ada sesi'}</span></div><div class="lesson-group-days">${body}</div></section>`;
  }).join('');
  document.querySelectorAll('.day-button').forEach(b=>b.addEventListener('click',()=>{
    persist();current=Number(b.dataset.day);const state=saved.days?.[current];checked=Boolean(state?.checked);answers=Array.isArray(state?.answers)?[...state.answers]:Array(10).fill('');persist();render();requestAnimationFrame(()=>document.getElementById('quiz-panel')?.scrollIntoView({behavior:'smooth',block:'start'}));
  }));
}
function render(){
  const d=lessons[current];renderDays();renderSemester();renderHistory();
  $('day-kicker').textContent=`HARI ${current+1} · ${d.type}`;$('day-title').textContent=d.name;$('day-desc').textContent=d.desc;$('day-tip').textContent=d.tip;
  const note=d.lessonNote||(d.type==='EXPERT'?'<b>Bekal Expert</b><span>Jadwal berulang yang bertemu lagi → cari KPK, lalu tambahkan selang waktunya ke jam/tanggal awal.</span><span>Membagi durasi menjadi bagian sama panjang terbesar → cari FPB.</span><small>Contoh: KPK(18, 24) = 72 menit; FPB(96, 144) = 48 menit.</small>':'');
  $('lesson-note').hidden=!note;
  if(note)$('lesson-note').innerHTML=note;
  $('questions').innerHTML=d.qs.map((q,i)=>{const good=checked&&answerMatches(answers[i],q[1]);return `<article class="question ${checked?(good?'correct':'incorrect'):''}"><div class="q-top"><span class="q-num">${String(i+1).padStart(2,'0')}</span><label class="q-text" for="answer-${i}">${q[0]}</label></div><div class="answer-wrap"><input id="answer-${i}" data-index="${i}" type="text" inputmode="text" autocomplete="off" ${i===0?'autofocus':''} placeholder="Tulis jawaban di sini" value="${escapeHtml(answers[i]||'')}" ${checked?'disabled':''} aria-label="Jawaban soal ${i+1}"></div>${checked?`<div class="feedback">${good?'Tepat! ':`Jawaban: ${answerLabel(q[1])}. `}${q[2]}</div>`:''}</article>`}).join('');
  document.querySelectorAll('.answer-wrap input').forEach(el=>el.addEventListener('input',e=>{answers[Number(e.target.dataset.index)]=e.target.value;updateProgress();persist();}));
  $('check-btn').disabled=checked;$('check-btn').textContent=checked?'Sudah diperiksa':'Periksa jawaban';
  $('reset-btn').onclick=()=>{checked=false;answers=Array(10).fill('');persist();render();};
  $('result').hidden=!checked;
  if(checked){const score=scoreDay();$('result').innerHTML=`${score===10?'Hebat sekali! ':score>=7?'Bagus! ':'Terus berlatih! '}Nilaimu ${score} dari 10.<small>${score===10?'Semua jawaban tepat. Kamu bisa lanjut ke hari berikutnya.':'Lihat pembahasan di bawah soal. Tekan “Ulangi hari ini” untuk mencoba kembali.'}</small>`;}
  $('check-btn').onclick=()=>{
    const missing=answers.filter(v=>!String(v).trim()).length;
    if(missing){$('result').hidden=false;$('result').innerHTML=`Masih ada ${missing} soal yang belum dijawab.<small>Isi semua jawaban dulu, lalu periksa lagi.</small>`;return;}
    const score=scoreDay();
    saved.records.push({day:current,score,total:d.qs.length,timestamp:new Date().toISOString()});
    checked=true;persist();render();
  };
  updateProgress();
}
function updateProgress(){const n=answers.filter(v=>String(v).trim()).length;$('progress-num').textContent=n;$('progress-bar').style.width=`${n*10}%`;}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
render();

